Object.assign(paths,{heart:'M12 21 3 12C-2 5 6 0 12 7c6-7 14-2 9 5Z',boot:'M8 3h8v10l5 3v5H3v-6l5-2Z',dodge:'m3 8 8-5-2 6h12M21 16l-8 5 2-6H3',pants:'M5 3h14l2 18h-7l-2-12-2 12H3ZM5 7h14'});
