const hero=`<svg viewBox="0 0 90 130" aria-hidden="true"><path fill="#273932" d="M29 40 16 92l15-4-2 30h30l-1-30 17 4-17-52Z"/><path fill="#86aaa0" d="m33 43-7 45 12-9-5 37h22l-5-37 12 9-9-45Z"/><path fill="#d7d7b7" d="m36 44 8 16 9-16-4 42H40Z"/><path fill="#1c2929" d="M32 14 38 8h15l7 9-3 23-7 8H38l-6-11Z"/><path fill="#cfb898" d="M36 22h18v14l-8 9-10-9Z"/><path fill="#c6d0c0" d="m32 21 25-4-5-7H39ZM36 9l8-7 5 8Z"/><path fill="#46685c" d="m23 50-11 28 8 4 17-34M55 48l13 34 7-4-10-27Z"/><path fill="#d3bb8d" d="M10 77h10v9H10ZM67 78h10v9H67Z"/><path fill="#bdccb9" d="m73 17 3 1-7 60-5-1Z"/><path fill="#bba16a" d="m60 74 15 2v4l-15-2ZM66 78l4 1-2 17-4-1Z"/><path fill="#172926" d="M31 117h12v8H29ZM47 117h12l3 8H47Z"/><path fill="#c8b77d" d="M35 78h21v4H35Z"/></svg>`;
let encyclopediaTab='equipment',bagItemTier='',bagItemQuality='',bagItemCategory='',bagItemSearch='';
let d,s,tab='home',bagTab='equipment',world='world_human',selectedMap=0,battleMode='normal',profession='meditation',homeTab='character',catalogCategory='',catalogSearch='',catalogPage=0,itemTier='',itemQuality='',gearSearch='',gearTier='',gearSlot='',gearPreviewQuality='white',gearPage=0,ownedTier='',ownedQuality='',ownedSlot='',alchemyTier='1',alchemyCategory='',alchemySearch='',alchemyPageIndex=0,alchemyIngredient='',alchemyCount=1,toastTimer,pendingAction=null,pendingSale=null,forgeTier='1',forgeSlot='',forgeCount=1,battleDetails=false,lastFxId=0,fxItems=[];
const mapViews=new Map(),mapGesture={pointers:new Map(),dragged:false,suppress:false};
const clock=n=>{n=Math.max(0,Math.floor(n));return String(Math.floor(n/3600)).padStart(2,'0')+':'+String(Math.floor(n%3600/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0')};
const key='van-dao-save-v1',navs=[['home','home','Động phủ'],['cultivation','person','Tu hành'],['battle','sword','Chiến đấu'],['world','map','Bản đồ'],['menu','bag','Menu']];
const names=activityNames;
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2600)}
let storageOK=true;function save(){s.last=Date.now();try{localStorage.setItem(key,JSON.stringify(s))}catch{if(storageOK)toast('Không thể lưu tự động. Hãy xuất bản lưu trong Cài đặt.');storageOK=false}}
const btn=(text,action,cls='',extra='')=>`<button class="${cls}" data-action="${action}" ${extra}>${text}</button>`;
function head(title,sub,tag='VẠN ĐẠO'){return `<div class="section-head"><h2>${title}</h2><span>${tag}</span></div>${sub?`<p class="section-sub">${sub}</p>`:''}`}
function info(){$('#stone-count').textContent=format(s.stones);const badge=$('#report-count');if(badge)badge.textContent=s.reports.filter(r=>!r.read).length||''}
function art(e,cls=''){const a=d.art[e.id||e];if(!a)return `<span class="entity-art ${cls}">${icon('star')}</span>`;return `<span class="entity-art ${a.pixel_art?'pixel-art ':''}${cls}"><img src="${a.src}" alt="${esc(a.name)}" loading="lazy" decoding="async" width="${a.width||384}" height="${a.height||384}"></span>`}
function characterArt(id=s.skin){const sk=d.skins.items.find(i=>i.id===id)||d.skins.items[0];return `<span class="character-art"><img src="${sk.src}" alt="${esc(sk.name)}" width="${sk.width}" height="${sk.height}" decoding="async"></span>`}
function qualityAttribute(id){return `data-quality="${gearTemplate(s,id,d)?gearQuality(s,id):d.items.items.find(i=>i.id===id)?.quality||'white'}"`}
function qualityLegend(){return `<details class="quality-legend"><summary>Phẩm chất trang bị</summary><div class="quality-swatches">${Object.entries(qualities).map(([id,q])=>`<span data-quality="${id}">${q.name}</span>`).join('')}</div></details>`}
function wardrobe(){return `<p class="wardrobe-note">Trang phục đổi ngoại hình, không cộng chỉ số. Mở theo cảnh giới; có thể xem trước mọi bộ.</p><div class="wardrobe-grid">${d.skins.items.map(sk=>{const allowed=canWearSkin(s,sk.id,d),equipped=s.skin===sk.id;return `<section class="skin-card ${equipped?'equipped':''}"><button class="skin-preview" data-preview-skin="${sk.id}" aria-label="Xem ${esc(sk.name)}">${characterArt(sk.id)}</button><h3>${esc(sk.name)}</h3><small>${d.cultivation.realms[sk.required_realm].name}</small><button class="${equipped?'outline':'primary'} full" data-wear-skin="${sk.id}" ${!allowed||equipped?'disabled':''}>${equipped?'Đang mặc':allowed?'Mặc trang phục':'Chưa đạt cảnh giới'}</button></section>`}).join('')}</div>`}
function skinDetails(id){const sk=d.skins.items.find(i=>i.id===id);if(!sk)return;modal(sk.name,`<div class="skin-modal-preview">${characterArt(id)}</div><p class="muted">Yêu cầu: ${d.cultivation.realms[sk.required_realm].name} · Ngoại hình, không đổi chỉ số.</p><button class="primary full" data-wear-skin="${sk.id}" ${!canWearSkin(s,id,d)||s.skin===id?'disabled':''}>${s.skin===id?'Đang mặc':canWearSkin(s,id,d)?'Mặc trang phục':'Chưa đạt cảnh giới'}</button>`)}
function locationImage(m){return d.locationVisuals.locations[m.id]?.src||worldVisual(mapWorld(m)).image}
function itemArt(id,cls=''){const a=d.itemArt.items[gearTemplate(s,id,d)?.id||id];if(!a)return `<span class="item-art ${cls}">${icon(itemIcon(id))}</span>`;if(a.kind==='image')return `<span class="item-art ${cls}" data-art-tier="${a.art_tier}"><img src="${a.src}" alt="${esc(itemName(id))}" width="${a.width}" height="${a.height}" loading="lazy" decoding="async"></span>`;return `<span class="item-art ${cls}" role="img" aria-label="${esc(itemName(id))}" data-art-tier="${a.art_tier}"><span class="item-sprite" style="background-image:url('${a.src}');background-size:${a.columns*100}% ${a.rows*100}%;background-position:${(a.column-1)/(a.columns-1)*100}% ${(a.row-1)/(a.rows-1)*100}%;--cell-aspect:${a.cell_aspect}"></span></span>`}
function showMapArt(id){const m=d.world.locations.find(m=>m.id===id);if(!m)return;modal(m.name,`<img class="map-art-preview" src="${locationImage(m)}" alt="${esc(m.name)}"><p class="muted">${m.requirement_label}</p>`)}
function itemName(id){const e=gearTemplate(s,id,d);return id==='potion'?'Hồi Xuân Đan':e?.display_name||e?.name||gearTemplate({},String(id).split('~')[0],d)?.display_name||d.items.items.find(x=>x.id===id)?.name||id}
function current(){return d.world.locations[s.map]}
function worldOf(m){return d.appendix.find(a=>a.id===m.id).world}
function mapWorld(m){return {'Nhân Giới':'world_human','Linh Giới':'world_spirit','Tiên Giới':'world_immortal'}[worldOf(m)]}
function worldVisual(id){return d.visuals[id]}
function worldPath(m){const a=d.appendix.find(a=>a.id===m.id);return [a.world,a.sector,a.country,a.region]}
function reportCard(r){return `<div class="card report-card"><div class="row"><h3>${esc(names[r.type])}</h3><span class="badge">${esc(r.reason)}</span></div><p class="muted">${clock(r.seconds)} · ${r.mode==='timed'?r.units+' quái':r.units+'/'+r.goal+' '+(r.type==='cultivate'?'giây':'lượt')}</p><div class="reward-grid"><span>Tu vi <b>+${format(r.exp)}</b></span><span>Linh thạch <b>+${format(r.stones)}</b></span>${r.spent?`<span>Đã dùng <b>${format(r.spent)} ◆</b></span>`:''}</div>${r.expLost!==undefined?`<p class="stat-down death-loss">Tử vong · −${format(r.expLost)} tu vi (10%)</p>`:''}${Object.entries(r.items).map(([id,n])=>`<p class="reward-item">${esc(itemName(id))} <b>×${n}</b></p>`).join('')}${r.gear.map(id=>`<p class="reward-item">${esc(itemName(id))} <b>×1</b></p>`).join('')}${r.metrics&&['fight','boss'].includes(r.type)?`<div class="combat-summary"><span>Sát thương <b>${format(r.metrics.damageDealt)}</b></span><span>Nhận vào <b>${format(r.metrics.damageTaken)}</b></span><span>Hồi phục <b>${format(r.metrics.healing)}</b></span><span>Dùng đan <b>${r.metrics.potions}</b></span><span>Kỹ năng <b>${r.metrics.skillCasts}</b></span>${r.metrics.mpSpent?`<span>MP đã dùng <b>${format(r.metrics.mpSpent)}</b></span>`:''}${r.metrics.petDamage?`<span>Linh thú gây <b>${format(r.metrics.petDamage)} sát thương</b></span>`:''}<span>EXP linh thú <b>+${r.metrics.petExp||0}</b></span><span>Bạo kích <b>${r.metrics.crits}</b></span></div>${Object.entries(r.metrics.kills).map(([id,n])=>`<p class="reward-item">${esc((d.combat.monsters.find(e=>e.id===id)||d.combat.bosses.find(e=>e.id===id))?.name||id)} <b>×${n}</b></p>`).join('')}`:''}${r.recipeResults?`<p class="recipe-summary">${r.recipeResults.success} mẻ thành công · ${r.recipeResults.failure} mẻ thất bại</p>`:''}${r.type==='pettrain'?'<p class="reward-item">Thú nuôi nhận 25 kinh nghiệm mỗi lượt.</p>':''}</div>`}
function activity(){const q=s.session;if(q?.journey)return journeyActivity();if(!q)return '';const recipe=recipeById(d,q.target),pct=Math.min(100,(q.type==='recipe'&&recipe?(q.units+(q.seconds%recipe.duration_seconds)/recipe.duration_seconds)/q.goal:q.mode==='timed'?q.seconds/q.duration:q.units/q.goal)*100),label=q.type==='cultivate'?'giây':q.type==='travel'?'chuyến':q.type==='recipe'?'mẻ':'lượt';return `<section class="activity-panel"><div class="row"><span class="activity-label">ĐANG THỰC HIỆN</span><span class="live">${clock(q.seconds)}</span></div><div class="activity-title">${icon(['fight','boss'].includes(q.type)?'sword':q.type==='craft'?'flask':q.type==='gather'?'leaf':'temple')}${names[q.type]}</div><div class="row muted"><span>${q.target?esc((d.combat.monsters.find(e=>e.id===q.target)||d.combat.bosses.find(e=>e.id===q.target))?.name||(q.type==='recipe'?itemName(recipeById(d,q.target)?.output_id||''):'')):current().name}</span><span>${q.mode==='timed'?clock(q.duration-q.seconds)+' còn lại · '+q.units+' quái':q.units+'/'+q.goal+' '+label}</span></div><div class="bar"><i style="width:${pct}%"></i></div><div class="activity-foot"><span>Kết quả sẽ được tổng kết khi kết thúc.</span>${btn('Kết thúc','stop','text-button')}</div></section>`}
function journeyActivity(){const q=s.session,j=q.journey,remaining=journeyRemaining(s,d),pct=j.mode==='walk'?j.travelledM/j.distanceM*100:Math.min(100,q.seconds/j.seconds*100),label={walk:'Di chuyển',teleport:'Truyền tống',ascend:j.upward?'Phi thăng':'Hạ giới'}[j.mode];return `<section class="activity-panel journey-panel"><div class="row"><span class="activity-label">${label.toLocaleUpperCase('vi')}</span><span class="live">${clock(remaining)} còn lại</span></div><h3>${esc(d.world.locations[j.from].name)} → ${esc(d.world.locations[j.to].name)}</h3><p class="muted">${j.mode==='walk'?`${format(j.travelledM)} / ${format(j.distanceM)} m · ${format(movementSpeed(s,d))} m/s`:j.mode==='teleport'?`Đã dùng ${format(j.cost)} linh thạch`:'Đang vượt qua tiếp điểm liên giới'}</p><div class="bar"><i style="width:${pct}%"></i></div><div class="activity-foot"><span>Dừng chuyến sẽ ở lại điểm xuất phát.${j.cost?' Phí đã dùng không hoàn lại.':''}</span>${btn('Dừng chuyến','stop','text-button')}</div></section>`}
function gateAt(i){const id=d.world.locations[i].id;return d.world.transport.gates.filter(g=>g.from===id||g.to===id)}
function gateDirection(g,i){const upward=d.world.locations[i].id===g.from;return {upward,to:d.world.locations.findIndex(m=>m.id===(upward?g.to:g.from))}}
function gatePanel(i){return gateAt(i).map(g=>{const {upward,to}=gateDirection(g,i),p=i===s.map?journeyPlan(s,d,to,'ascend'):null;return `<section class="card gate-card"><span class="activity-label">2.3 · TIẾP ĐIỂM PHI THĂNG</span><h3>${esc(g.name)}</h3><p>${esc(d.world.locations[i].name)} ⇄ ${esc(d.world.locations[to].name)}</p><p class="muted">${upward?'Yêu cầu '+d.cultivation.realms[g.required_realm].name+' · thắng Boss tại '+d.world.locations[g.boss_map].name:'Hạ giới qua tiếp điểm đã khai thông'} · Nghi thức ${g.seconds} giây</p>${i===s.map?`<button class="gold-button full" data-gate-route="${to}" ${p.ok?'':'disabled'}>${upward?'Phi thăng':'Hạ giới'}</button>${p.ok?'':`<p class="muted">${esc(p.reason)}</p>`}`:'<p class="muted">Đến tiếp điểm này để thực hiện nghi thức.</p>'}</section>`}).join('')}
function crossWorldGuide(to){const worlds=d.world.worlds.map(w=>w.id),here=worlds.indexOf(locationWorld(d,s.map)),there=worlds.indexOf(locationWorld(d,to)),up=there>here,g=d.world.transport.gates.find(g=>locationWorld(d,d.world.locations.findIndex(m=>m.id===(up?g.from:g.to)))===worlds[here]);if(!g)return '';const at=d.world.locations.findIndex(m=>m.id===(up?g.from:g.to));return `<div class="notice">Khác giới · Hãy đến <b>${esc(d.world.locations[at].name)}</b>, qua ${esc(g.name)} rồi tiếp tục hành trình.<button class="outline full" data-gate-view="${at}">Xem tiếp điểm ${up?'phi thăng':'hạ giới'} →</button></div>`}
function routeSteps(from,to){const step=to>from?1:-1;let html='';for(let i=from;i!==to;i+=step)html+=`<p>${esc(d.world.locations[i].name)} → ${esc(d.world.locations[i+step].name)} · <b>${format(routeDistance(d,i,i+step))} m</b></p>`;return html}
function transportPanel(i){if(i===s.map)return `<div class="travel-summary"><span>Trận truyền tống đã kích hoạt</span><b>${format(movementSpeed(s,d))} m/s</b></div>`+gatePanel(i);const distance=routeDistance(d,s.map,i);return `<section class="card route-card"><span class="activity-label">2.1–2.2 · HÀNH TRÌNH</span><h3>${esc(current().name)} → ${esc(d.world.locations[i].name)}</h3>${distance===null?crossWorldGuide(i):`<div class="travel-metrics"><span>Quãng đường<b>${format(distance)} m</b></span><span>Tốc độ<b>${format(movementSpeed(s,d))} m/s</b></span><span>Thời gian đi<b>${clock(Math.ceil(distance/movementSpeed(s,d)))}</b></span></div><details class="route-steps"><summary>Xem các chặng đường</summary>${routeSteps(s.map,i)}</details><p class="muted">Trận truyền tống: ${s.visitedMaps.includes(i)?'đã kích hoạt':'chưa kích hoạt · đến lần đầu bằng đường thường'}.</p>`}</section>`+gatePanel(i)}
function travelChoice(i,toBattle=false,onlyMode=null){const distance=routeDistance(d,s.map,i);if(distance===null&&!onlyMode){modal('Hành trình liên giới',crossWorldGuide(i)+gatePanel(s.map));return}const modes=onlyMode?[onlyMode]:['walk','teleport'];modal('Chọn cách di chuyển',`<p><b>${esc(current().name)}</b> → <b>${esc(d.world.locations[i].name)}</b></p>${distance===null?'':`<p class="muted">${format(distance)} m · Tốc độ ${format(movementSpeed(s,d))} m/s</p>`}`+modes.map(mode=>{const p=journeyPlan({...s,activity:null},d,i,mode),label={walk:'Di chuyển',teleport:'Truyền tống',ascend:locationWorld(d,i)===locationWorld(d,s.map)?'Qua tiếp điểm':d.world.worlds.findIndex(w=>w.id===locationWorld(d,i))>d.world.worlds.findIndex(w=>w.id===locationWorld(d,s.map))?'Phi thăng':'Hạ giới'}[mode];return `<section class="route-option"><h3>${label}</h3><p class="muted">${p.ok?`${clock(p.seconds)} · ${p.cost?format(p.cost)+' linh thạch':'Không tốn linh thạch'}`:esc(p.reason)}</p><button class="${mode==='walk'?'primary':'gold-button'} full" data-route-to="${i}" data-route-mode="${mode}" data-route-battle="${toBattle?'yes':'no'}" ${p.ok?'':'disabled'}>${label}</button></section>`}).join('')+`<p class="muted">${onlyMode?'Nghi thức không phụ thuộc tốc độ.':'Đi đường thường phụ thuộc tốc độ. Truyền tống mất 3 giây và cần trận đích đã kích hoạt.'} Nếu dừng, bạn ở lại điểm xuất phát; phí truyền tống đã dùng không hoàn lại.</p>`)}
function equipmentView(){const slots=[['weapon','Vũ khí'],['head','Nón'],['chest','Áo'],['pants','Quần'],['feet','Giày'],['pendant','Ngọc bội']];return `<div class="equipment-grid">${slots.map(([slot,label])=>{const id=s.equipment[slot],e=gearTemplate(s,id,d);return `<button class="gear-slot ${e?'worn':''}" ${e?qualityAttribute(id):''} ${e?`data-item="${id}"`:`data-slot="${slot}"`}>${e?itemArt(id):icon(slot==='weapon'?'sword':'shield')}<strong>${label}</strong><small>${e?esc(itemName(id)):'Chưa trang bị'}</small>${e?`<span class="tier-badge">Bậc ${romanTier(e.tier)}</span>`:''}</button>`}).join('')}</div>`}
function home(){return `<button class="abode-hero" data-tab="combatStats" aria-label="Tu luyện và đột phá"><div class="abode-portrait">${characterArt()}</div><div><strong>${esc(s.name)}</strong><h3>${cultivationLabel(s,d)}</h3><span class="root-attribute">◈ Linh căn: Kim · Ngũ hành Kim</span></div></button>`+cultivationProgress()+activity()+`<div class="tabs home-tabs" role="tablist">${[['character','Nhân vật'],['skills','Công pháp'],['pets','Linh thú']].map(([id,name])=>`<button role="tab" aria-selected="${homeTab===id}" class="${homeTab===id?'active':''}" data-home-tab="${id}">${name}</button>`).join('')}</div>`+(homeTab==='skills'?skillView():homeTab==='pets'?pets():characterView())}
function cultivationProgress(){const required=+level(s,d).exp_bar,value=Math.max(0,Math.min(required,s.exp)),pct=required?value/required*100:100;return `<section class="cultivation-progress"><div class="row"><span>Tu vi</span><b>${format(value)} / ${format(required)} · ${Intl.NumberFormat('vi-VN',{maximumFractionDigits:1}).format(pct)}%</b></div><div class="bar gold" role="progressbar" aria-label="Tiến độ tu vi" aria-valuemin="0" aria-valuemax="${required}" aria-valuenow="${value}"><i style="width:${pct}%"></i></div></section>`}
function characterView(){return equipmentView()+head('Chỉ số nhân vật','','NHÂN VẬT')+statCard()+`<div class="row abode-links"><button class="text-button" data-tab="bag">Hành trang →</button></div>`}

function statIcon(k){return `<span class="stat-icon" title="${statInfo[k]?.name||k}" aria-label="${statInfo[k]?.name||k}">${icon(({attack:'sword',hp:'heart',mp:'flask',defense:'shield',speed:'boot',dodge:'dodge',attackSpeed:'clock',cooldownReduction:'clock',damageReduction:'shield',critRate:'star',critDamage:'sword'})[k]||'star')}</span>`}
function gearDelta(id){const e=gearTemplate(s,id,d);if(!e||s.equipment[e.slot]===id)return '';const cmp=gearComparison(s,id,d),values=gearValues(s,id,d);return `<span class="gear-delta">${Object.entries(statInfo).filter(([k])=>Math.abs(cmp.delta[k])>.000001).map(([k,meta])=>`<span class="${cmp.delta[k]>0?'stat-up':'stat-down'}">${statIcon(k)} ${meta.name} +${statText(k,values[k])} <b>${cmp.delta[k]>0?'↑':'↓'} ${statText(k,Math.abs(cmp.delta[k]))}</b></span>`).join('')||'<span class="muted">Không đổi</span>'}</span>`}
function inventoryStat(id){const e=gearTemplate(s,id,d),i=d.items.items.find(i=>i.id===id),main=e?gearBase(s,id,d):null,key=main?.stat||({attack_pill:'attack',hp_pill:'hp',defense_pill:'defense',recovery:'hp',cultivation_pill:'mp'})[i?.category]||(id==='potion'?'hp':null);if(!key)return '';const delta=e&&s.equipment[e.slot]!==id?gearComparison(s,id,d).delta[key]:0;return `<span class="inventory-stat" data-stat="${key}">${statIcon(key)}<span>${main?'+'+statText(key,main.value):id==='potion'?'40%':i?.value?'+'+format(+i.value):''}</span>${delta?`<em class="${delta>0?'stat-up':'stat-down'}">${delta>0?'↑':'↓'}${statText(key,Math.abs(delta))}</em>`:''}</span>`}

function statCard(){const st=stats(s,d);return `<div class="character-stat-list">${Object.entries(statInfo).filter(([k])=>!k.endsWith('Percent')).map(([key,meta])=>`<div class="stat-line">${statIcon(key)}<span>${meta.name}</span><b>${key==='mp'?format(s.mp??st.mp)+' / ':''}${statText(key,st[key])}${key==='attackSpeed'?` <small>(${Intl.NumberFormat('vi-VN',{maximumFractionDigits:3}).format(actionDelay(s,d))} giây/lượt)</small>`:''}</b></div>`).join('')}</div>`}

function cultivation(){const entries=[['combat','sword','Chiến đấu',cultivationLabel(s,d),'Tu vi và đột phá'],['alchemy','flask','Luyện đan','Lv. '+professionLevel(s,'alchemy'),'Đan dược và hồi phục'],['forging','shield','Luyện khí','Lv. '+professionLevel(s,'forging'),'Rèn trang bị'],['meditation','temple','Thiền tu luyện','Lv. '+professionLevel(s,'meditation'),'Tích lũy tu vi']];return head('Tu hành','Chạm vào cấp độ để mở các hoạt động tương ứng.','CẢNH GIỚI & NGHỀ')+`<div class="discipline-grid">${entries.map(([id,i,n,l,sub])=>`<button class="discipline-card" ${id==='combat'?'data-tab="combatStats"':`data-profession="${id}"`}>${icon(i)}<span>${n}</span><strong>${l}</strong><small>${sub} →</small></button>`).join('')}</div><button class="outline full" data-home-tab="character">Chỉ số nhân vật →</button>${s.session?'<div class="section-head"><h3>Đang thực hiện</h3></div>':''}${activity()}`}
function combatStats(){const l=level(s,d);return head('Cảnh giới & đột phá',cultivationLabel(s,d),'CẢNH GIỚI')+`<div class="card" style="margin-top:14px"><h3>Đột phá</h3>${cultivationProgress()}${btn(s.realm===8&&s.floor===4?'Đã đạt Đỉnh phong':s.floor===maxPhase(s)?'Đột phá đại cảnh giới':s.realm===0?'Đột phá tầng tiếp theo':'Đột phá giai đoạn tiếp theo','breakthrough','gold-button full',s.exp<+l.exp_bar||(s.realm===8&&s.floor===4)?'disabled':'')}</div><button class="gold-button full" data-profession="meditation">Thiền tu luyện →</button><button class="primary full" data-tab="battle">Đến chiến trường →</button><button class="outline full" data-tab="skills" style="margin-top:9px">Công pháp và bí thuật →</button>`}
function alchemyPage(){return head('Luyện đan','Lv. '+professionLevel(s,'alchemy')+' · Chọn công thức để luyện','8.1 · ĐAN PHƯƠNG')+`<div class="recipe-book-intro"><strong>Đan phương & Linh Dịch</strong><p>Hồi phục, tu vi, đan tăng chỉ số và nguyên liệu tinh luyện.</p></div>${activity()}<div class="catalog-filters alchemy-filters"><input id="alchemy-search" type="search" placeholder="Tìm tên đan hoặc nguyên liệu…" value="${esc(alchemySearch)}"><select id="alchemy-tier">${tierOptions(alchemyTier,true)}</select><select id="alchemy-category"><option value="">Tất cả công thức</option>${[['recovery','Hồi phục'],['cultivation_pill','Tu vi'],['attack_pill','Tăng ATK'],['hp_pill','Tăng HP'],['defense_pill','Tăng DEF'],['processed_material','Linh Dịch'],['breakthrough_pill','Đột phá · chưa mở']].map(([id,label])=>`<option value="${id}" ${alchemyCategory===id?'selected':''}>${label}</option>`).join('')}</select><label>Số mẻ<input id="alchemy-count" type="number" min="1" max="100" step="1" value="${alchemyCount}"></label></div>${alchemyIngredient?`<p class="muted">Liên quan: ${esc(itemName(alchemyIngredient))} <button class="text-button" data-action="alchemy-clear">Bỏ lọc</button></p>`:''}<p class="muted">Trừ nguyên liệu và phí từng mẻ khi hoàn tất. Thất bại vẫn tiêu hao; dừng giữ phần chưa dùng. Nhấn tên nguyên liệu để xem cách kiếm.</p><div id="alchemy-results">${alchemyResults()}</div>`}
function alchemyResults(){const ranks={recovery:0,processed_material:1,cultivation_pill:2,attack_pill:3,hp_pill:4,defense_pill:5,breakthrough_pill:6};const all=d.items.recipes.filter(r=>{if(r.discipline!=='alchemy')return false;const o=recipeOutput(r,d);return o&&(!alchemyTier||o.tier===+alchemyTier||o.tier===0&&alchemyTier!=='0')&&(!alchemyCategory||o.category===alchemyCategory)&&(!alchemyIngredient||r.output_id===alchemyIngredient||r.inputs.some(i=>i.item_id===alchemyIngredient))&&(itemName(r.output_id)+' '+r.inputs.map(i=>itemName(i.item_id)).join(' ')).toLocaleLowerCase('vi').includes(alchemySearch.toLocaleLowerCase('vi'))}).sort((a,b)=>{const x=recipeOutput(a,d),y=recipeOutput(b,d);return x.tier-y.tier||(ranks[x.category]??9)-(ranks[y.category]??9)}),start=alchemyPageIndex*8;return `<p class="muted">${all.length} công thức · ${Math.min(start+1,all.length)}–${Math.min(start+8,all.length)}</p>${all.slice(start,start+8).map(r=>recipeView(r,true)).join('')}${all.length?'':'<div class="empty">Không có công thức phù hợp bộ lọc.</div>'}<div class="row catalog-pages"><button data-alchemy-page="${alchemyPageIndex-1}" ${alchemyPageIndex===0?'disabled':''}>← Trước</button><span>${alchemyPageIndex+1}/${Math.max(1,Math.ceil(all.length/8))}</span><button data-alchemy-page="${alchemyPageIndex+1}" ${start+8>=all.length?'disabled':''}>Sau →</button></div>`}
function professionPage(){if(profession==='alchemy')return alchemyPage();if(profession==='forging')return forgingPage();const data={alchemy:['Luyện đan','flask','craft','5 Hoàng Tinh Thảo + 10 linh thạch / lượt','8 giây / lượt · 1 Hồi Xuân Đan · +15 EXP nghề'],forging:['Luyện khí','shield','forge',`3 ${resource(d,s.map,'ore').name} + 80 linh thạch / lượt`,'12 giây / lượt · 1 món tại địa điểm hiện tại · +25 EXP nghề'],meditation:['Thiền tu luyện','temple','cultivate','Không tiêu hao nguyên liệu','+6 tu vi / giây · Dừng khi đủ thời gian hoặc đầy tu vi']},[n,i,a,cost,reward]=data[profession];return head(n,'Lv. '+professionLevel(s,profession)+' · '+(s.professions[profession]%100)+'/100 EXP đến cấp tiếp theo','TU HÀNH')+`<div class="profession-hero">${icon(i)}<h3>${n}</h3></div><div class="card"><strong>${cost}</strong><p class="muted">${reward}</p><label class="setting-label" for="plan-count">${a==='cultivate'?'Số giây thiền':'Số lượt thực hiện'}</label><input id="plan-count" type="number" min="1" max="${a==='cultivate'?28800:1000}" value="${a==='cultivate'?60:1}"><button class="gold-button full" data-begin="${a}" style="margin-top:12px">Bắt đầu ${n.toLowerCase()}</button><p class="muted">Chỉ một hoạt động tại một thời điểm. Tổng kết xuất hiện khi hoàn tất hoặc dừng.</p></div>${profession==='forging'?`<button class="outline full" data-begin="mine">Khai thác ${resource(d,s.map,'ore').name}</button>`:profession==='alchemy'?'<button class="outline full" data-action="go-herbs">Tìm Hoàng Tinh Thảo ở Vô Danh Thôn →</button>':''}${activity()}`}
function atlasNode(m,n,overview=false){return `<button class="atlas-node atlas-location-label ${overview?'overview-location ':''}${m.i===s.map?'is-current':''} ${gateAt(m.i).length?'is-gate':''}" style="left:${n.lx}%;top:${n.ly}%" data-location="${m.i}"><strong>${m.name}</strong><small>${m.requirement_label}</small></button>`}
function atlasPointers(maps,nodes,overview=false){return `<svg class="atlas-annotations ${overview?'overview-location':''}" viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true">${maps.map(m=>{const n=nodes[m.id];return `<line x1="${n.x}" y1="${n.y}" x2="${n.lx}" y2="${n.ly}"/><circle cx="${n.x}" cy="${n.y}" r="0.5"/>`}).join('')}</svg>`}
function updateAtlasJourney(){if(tab!=='world')return;const marker=$('.atlas-character');if(marker?.style){const p=journeyMapPosition(s,d);marker.style.left=p.x+'%';marker.style.top=p.y+'%'}}
function worldView(){const v=worldVisual(world),regions=worldRegions(d,world),maps=worldLocations(d,world);return `<div class="tabs world-tabs">${d.world.worlds.map(w=>`<button data-world="${w.id}" class="${world===w.id?'active':''}">${w.name}</button>`).join('')}</div><div class="travel-summary"><span>Tốc độ di chuyển</span><b>${format(movementSpeed(s,d))} m/s</b></div><div class="world-view compact-map overview-map clean-atlas map-viewport continuous-atlas ${v.kind}" aria-label="Bản đồ ${v.name}"><div class="world-canvas map-scene"><img src="${v.image}" alt="Toàn cảnh ${v.name}">${regions.map(r=>`<button class="atlas-node atlas-region-label ${r.id===current().parent_id?'is-current':''}" style="left:${r.x}%;top:${r.y}%" data-region="${r.id}"><strong>${r.name}</strong><small>${r.locations[0].requirement_label}</small></button>`).join('')}${maps.map(m=>atlasNode(m,d.nodes[m.id],true)).join('')}${maps.some(m=>m.i===s.map)?`<span class="atlas-character" style="left:${journeyMapPosition(s,d).x}%;top:${journeyMapPosition(s,d).y}%" role="img" aria-label="Vị trí nhân vật">${characterArt()}</span>`:''}</div></div><details class="gate-directory"><summary>2.3 · Tiếp điểm phi thăng</summary>${d.world.transport.gates.map(g=>`<button class="menu-item" data-gate-view="${d.world.locations.findIndex(m=>m.id===g.from)}"><span><strong>${esc(g.name)}</strong><small>${esc(d.world.locations.find(m=>m.id===g.from).name)} → ${esc(d.world.locations.find(m=>m.id===g.to).name)}</small></span><b>›</b></button>`).join('')}</details>`}
function locationPage(){const m=d.world.locations[selectedMap],mon=d.combat.monsters.filter(e=>e.map_id===m.id),boss=d.combat.bosses.find(e=>e.map_id===m.id),herb=resource(d,selectedMap,'herb'),ore=resource(d,selectedMap,'ore'),a=d.appendix[selectedMap];return head(m.name,`${a.world} · ${a.region}`,'M'+String(selectedMap+1).padStart(2,'0'))+`<div class="location-banner" style="background-image:linear-gradient(0deg,#102021e8,#10202133),url('${locationImage(m)}')"><span class="badge">${m.requirement_label}</span><button class="map-art-open" data-map-art="${m.id}">Xem cảnh</button></div><div class="row location-actions"><button class="outline" data-tab="world">← Bản đồ</button>${selectedMap===s.map?'<button class="primary" data-map-battle="'+selectedMap+'">Chiến đấu</button>':`<button class="primary" data-travel="${selectedMap}" ${!canEnter(s,d,selectedMap)?'disabled':''}>${!canEnter(s,d,selectedMap)?'Chưa đủ điều kiện':'Di chuyển đến đây'}</button>`}${selectedMap!==s.map?`<button class="gold-button" data-map-battle="${selectedMap}" ${!canEnter(s,d,selectedMap)?'disabled':''}>Đến chiến đấu</button>`:''}</div>${!canEnter(s,d,selectedMap)&&selectedMap!==s.map?`<p class="muted">Yêu cầu: ${m.requirement_label}.${selectedMap>s.unlocked?' Cần thắng Boss ở '+d.world.locations[selectedMap-1].name+' để mở đường.':''}</p>`:''}${transportPanel(selectedMap)}<div class="section-head"><h3>Quái vật</h3><span>CHẠM ĐỂ XEM CHỈ SỐ & ĐỒ RƠI</span></div><div class="enemy-grid">${mon.map(e=>`<button class="enemy-card" data-entity="${e.id}">${art(e)}<strong class="entity-name">${esc(e.name)}</strong><small>${format(+e.hp)} HP</small></button>`).join('')}</div><div class="section-head"><h3>Boss địa điểm</h3></div><button class="boss-location" data-entity="${boss.id}">${art(boss)}<span><strong>${boss.name}</strong><small>${format(+boss.hp)} HP · Xem chỉ số và vật phẩm →</small></span></button><div class="section-head"><h3>Tài nguyên</h3></div><div class="resource-grid"><button data-resource="${herb.id}" class="resource-card">${itemArt(herb.id)}<strong>${herb.name}</strong><small>Thảo dược · Thu thập 5 giây/lượt</small></button><button data-resource="${ore.id}" class="resource-card">${itemArt(ore.id)}<strong>${ore.name}</strong><small>Khoáng vật · Khai thác 5 giây/lượt</small></button></div>`}
function entityDetails(id){const e=d.combat.monsters.find(x=>x.id===id)||d.combat.bosses.find(x=>x.id===id);if(!e)return;const l=loot(d,e),idx=d.world.locations.findIndex(m=>m.id===e.map_id),boss=id.startsWith('boss_');modal(e.name,`<div class="entity-detail-art">${art(e)}</div><p class="muted">${d.world.locations[idx].name} · ${boss?'Boss':'Quái thường'}</p><div class="character-stat-list entity-stat-list"><div class="stat-line"><span>HP</span><b>${format(+e.hp)}</b></div><div class="stat-line"><span>ATK</span><b>${format(+e.attack)}</b></div><div class="stat-line"><span>DEF</span><b>${format(+e.defense)}</b></div></div><p class="muted">Tốc đánh ${e.attack_speed||'1.0'}/s</p>${boss?`<p class="muted">Kỹ năng GDD: ${d.combat.boss_skills.filter(x=>x.boss_id===id).map(x=>esc(x.name)).join(' · ')}</p>`:''}<h3 style="margin-top:16px">Phần thưởng & đồ rơi</h3><div class="reward-grid"><span>Tu vi <b>+${format(l.exp)}</b></span><span>Linh thạch <b>+${format(l.stones)}</b></span></div>${l.soul?`<p class="reward-item">${l.soul.name} · ×1 mỗi lần thắng</p>`:''}<p class="muted">${l.equipmentRule}. Mẫu rơi ngẫu nhiên; mỗi bản sao giữ chỉ số riêng.</p><div class="drop-list">${l.equipment.map(eq=>`<span>${esc(itemName(eq.id))}</span>`).join('')}</div>${boss?'<p class="muted">Boss có thời gian niệm kỹ năng, lá chắn và hiệu ứng chiến đấu. Giới hạn 3 phút mỗi lần khiêu chiến.</p>':'<p class="muted">Auto chọn ngẫu nhiên cả 3 loại quái của map, tối đa 4 giờ mỗi phiên.</p>'}<button class="gold-button full" data-start-entity="${id}" ${idx!==s.map?'disabled':''}>${boss?'Khiêu chiến Boss · 1 lượt':'Auto săn tại map · tối đa 4 giờ'}</button>${idx!==s.map?'<p class="muted">Hãy di chuyển đến địa điểm này trước khi chiến đấu.</p>':''}`)}
function resourceDetails(id){const r=d.items.items.find(x=>x.id===id);if(!r)return;const idx=d.world.locations.findIndex(m=>m.id===r.source_map_id);modal(r.name,itemCard(r,id)+`<section class="item-sources"><h3>Nguồn thu thập</h3><p>${esc(d.world.locations[idx].name)} · 5 giây/lượt · 1 nguyên liệu/lượt · +8 tu vi khi thanh chưa đầy.</p><p>Kế hoạch: 10 lượt, báo cáo tổng khi kết thúc.</p><button class="gold-button full" data-start-resource="${id}" ${idx!==s.map?'disabled':''}>${r.category==='herb'?'Thu thập':'Khai thác'} 10 lượt</button>${idx!==s.map?'<p class="muted">Cần di chuyển đến địa điểm này.</p>':''}<button class="outline full" data-item="${id}">Công thức & chi tiết vật phẩm →</button></section></div></section>`,r.quality||'white')}

function skillBar(){const active=combatSkills(s,d),q=s.session,c=s.combat;return `<div class="skill-strip" aria-label="5 ô kỹ năng">${Array.from({length:5},(_,index)=>{const a=active[index],cd=a?Math.max(0,(c?.cooldowns?.[a.id]||0)-(q?.seconds||0)):0,total=a?Math.max(1,+a.cooldown_seconds*(1-stats(s,d).cooldownReduction)):1;return `<button class="skill-icon ${cd?'cooling':''} ${a?'':'empty'}" ${a?`data-skill-info="${a.id}"`:'data-tab="skills"'} title="${a?esc(a.name):'Ô kỹ năng trống'}" aria-label="${a?esc(a.name)+(cd?' · hồi chiêu '+Math.ceil(cd)+' giây':' · sẵn sàng'):'Trang bị kỹ năng ô '+(index+1)}" style="--cooldown:${Math.min(1,cd/total)*100}%">${a?icon(['sword','star','shield','leaf','flask'][index]):'+'}${cd?`<span>${Math.ceil(cd)}</span>`:''}</button>`}).join('')}</div>`}
function skillInfo(id){const a=d.arts.arts.find(a=>a.id===id);if(!a||!s.skills[id])return;const cd=Math.max(0,(s.combat?.cooldowns?.[id]||0)-(s.session?.seconds||0)),coefficient=+a.direct_attack_coefficient*(1+.05*(s.skills[id]-1));modal(a.name,`<div class="skill-info-symbol">${icon(+a.direct_attack_coefficient>0?'sword':'shield')}</div><p>Cấp ${s.skills[id]} · ${coefficient>0?'Sát thương ×'+coefficient.toFixed(2):'Hồi 8% HP và tạo lá chắn 8% HP trong 6 giây'}</p><p>Hồi chiêu ${format(+a.cooldown_seconds*(1-stats(s,d).cooldownReduction))} giây${cd?' · còn '+Math.ceil(cd)+' giây':' · sẵn sàng'}</p><p class="muted">Tiêu hao ${format(skillCost(a))} MP mỗi lần. Thực hiện lần lượt theo ô; mỗi lượt cách ${Intl.NumberFormat('vi-VN',{maximumFractionDigits:3}).format(actionDelay(s,d))} giây. Thiếu MP hoặc đang hồi chiêu thì chuyển kỹ năng sẵn sàng/đánh thường.</p><button class="outline full" data-tab="skills">Sắp xếp kỹ năng →</button>`)}
function syncBattleEffects(){const latest=s.combatEventSerial||0,now=Date.now();if(tab!=='battle'||!['fight','boss'].includes(s.activity)||$('#modal').open){lastFxId=latest;fxItems=[];return}const kinds={hit:['enemy','damage','−','HP'],crit:['enemy','critical','−','HP'],hurt:['hero','damage','−','HP'],heal:['hero','healing','+','HP'],mana:['hero','mana','−','MP'],'mana-heal':['hero','mana-gain','+','MP'],dodge:['hero','avoid','',''],miss:['enemy','avoid','','']};for(const e of [...s.battleLog].reverse()){if(!e.eventId||e.eventId<=lastFxId||!kinds[e.kind]||(!e.value&&!['dodge','miss'].includes(e.kind)))continue;const [target,kind,sign,unit]=kinds[e.kind];fxItems.push({id:e.eventId,target,kind,text:unit?sign+format(e.value)+' '+unit:'Né tránh',born:now})}lastFxId=latest;fxItems=fxItems.filter(e=>now-e.born<1800).slice(-16)}
function battleEffects(target){const now=Date.now();return `<div class="combat-fx-layer" aria-live="polite" aria-atomic="false">${fxItems.filter(e=>e.target===target).slice(-6).map((e,index)=>`<span class="combat-float ${e.kind}" style="--fx-lane:${index%3};animation-delay:-${Math.max(0,now-e.born)}ms">${e.text}</span>`).join('')}</div>`}
function battle(){const ongoing=['fight','boss'].includes(s.activity),e=ongoing?encounter(s,d):null,st=stats(s,d),q=s.session,c=s.combat,list=battleMode==='boss'?[d.combat.bosses[s.map]]:d.combat.monsters.filter(e=>e.map_id===current().id),settings=s.battleSettings,skills=combatSkills(s,d),metrics=ongoing?q.metrics:s.reports.find(r=>['fight','boss'].includes(r.type))?.metrics;
return battleMap()+head('Chiến đấu','','LỊCH LUYỆN')+`<div class="tabs combat-tabs"><button data-combat-mode="normal" class="${battleMode==='normal'?'active':''}">Chiến đấu thường</button><button data-combat-mode="boss" class="${battleMode==='boss'?'active':''}">Đánh Boss</button></div><div class="battle-tools">${btn('Chi tiết','battle-details','outline',`aria-expanded="${battleDetails}"`)}</div>
${ongoing?`<div class="card combat-live"><div class="row"><span class="badge">${names[s.activity]}</span><span class="live">${q.mode==='timed'?clock(q.duration-q.seconds)+' còn lại':clock(q.seconds)}</span></div>${battleDetails?`<p class="combat-totals">Tổng chỉ số · HP ${format(st.hp)} · ATK ${format(st.attack)} · DEF ${format(st.defense)}</p>`:''}<div class="combat-stage battle-scene" style="background-image:linear-gradient(#07191b22,#07191b99),url('${locationImage(current())}')"><div class="combat-actor hero-actor">${characterArt()}${battleEffects('hero')}<b>${esc(s.name)}</b><div class="bar"><i style="width:${s.hp/st.hp*100}%"></i></div><small>${format(Math.round(s.hp))} / ${format(st.hp)} HP<span class="combat-mp">${format(s.mp??st.mp)} / ${format(st.mp)} MP</span></small>${skillBar()}</div><span class="vs">VS</span><div class="combat-actor enemy-actor">${art(e)}${battleEffects('enemy')}<b class="entity-name">${esc(e.name)}</b><div class="bar red"><i style="width:${(s.enemy?s.enemy.current:+e.hp)/+e.hp*100}%"></i></div><small>${format(Math.max(0,s.enemy?s.enemy.current:+e.hp))} / ${format(+e.hp)} HP</small></div></div>${battleDetails&&s.pet?.active?petCombatView():''}${c?.cast?`<div class="cast-bar">${esc(d.combat.boss_skills.find(a=>a.id===c.cast.id)?.name||'Kỹ năng Boss')} · niệm ${Math.max(0,c.cast.at-q.seconds)}s</div>`:''}${battleDetails&&c?.enemyShieldUntil>=q.seconds&&c.enemyShield?`<p class="muted">Lá chắn Boss: ${format(c.enemyShield)}</p>`:''}<div class="row">${btn('Dùng đan','heal','outline',s.bag.potion<1||q.seconds<(c?.potionReady||0)?'disabled':'')}${btn('Dừng & tổng kết','stop','outline')}</div></div>`:`<div class="card idle-combat-character">${characterArt()}${skillBar()}${battleMode==='normal'?'<button class="gold-button full" data-auto-fight="true">Auto săn quái</button>':`<button class="gold-button full" data-start-entity="${list[0].id}">Khiêu chiến Boss</button>`}</div>`}

${metrics&&battleDetails?`<div class="combat-summary"><span>Đã hạ <b>${Object.values(metrics.kills).reduce((a,b)=>a+b,0)}</b></span><span>DPS <b>${format(metrics.damageDealt/Math.max(1,ongoing?q.seconds:s.reports.find(r=>r.metrics===metrics)?.seconds||1))}</b></span><span>Sát thương <b>${format(metrics.damageDealt)}</b></span><span>Nhận vào <b>${format(metrics.damageTaken)}</b></span><span>Hồi phục <b>${format(metrics.healing)}</b></span><span>Dùng đan <b>${metrics.potions}</b></span></div>`:''}

`}
function battleMap(){const monsters=d.combat.monsters.filter(e=>e.map_id===current().id),boss=d.combat.bosses[s.map];return `<section class="battle-map" style="background-image:linear-gradient(#102021b3,#102021ed),url('${locationImage(current())}')"><div class="row"><strong>Đang ở: ${esc(current().name)}</strong><button class="text-button" data-tab="world">Đổi map →</button></div><div class="map-inhabitants">${[...monsters,boss].map(e=>`<button data-entity="${e.id}">${art(e)}<strong class="entity-name">${e===boss?'Boss · ':''}${esc(e.name)}</strong></button>`).join('')}</div></section>`}
function autoSetup(){const cfg=s.battleSettings;modal('Chuẩn bị auto săn',`<p class="muted">${esc(current().name)} · Ngẫu nhiên 3 loại quái</p><div class="auto-form"><label>Thời gian<select id="auto-duration">${[3600,7200,14400].map(n=>`<option value="${n}" ${n===cfg.duration?'selected':''}>${n/3600} giờ</option>`).join('')}</select></label><label><span><input id="auto-potion" type="checkbox" ${cfg.autoPotion?'checked':''}> Tự dùng Hồi Xuân Đan</span></label><label>Đan mang theo · túi có ${s.bag.potion||0}<input id="auto-stock" type="number" min="0" max="${s.bag.potion||0}" value="${Math.min(s.bag.potion||0,cfg.potionLimit??9999)}"></label><label>Dùng khi HP dưới<select id="auto-threshold">${[.3,.5,.7].map(n=>`<option value="${n}" ${cfg.potionThreshold===n?'selected':''}>${n*100}%</option>`).join('')}</select></label><label>Rút lui khi HP dưới<select id="auto-retreat">${[0,.15,.3].map(n=>`<option value="${n}" ${cfg.retreatHP===n?'selected':''}>${n?n*100+'%':'Chỉ dừng khi cạn HP'}</option>`).join('')}</select></label><label><span><input id="auto-skills" type="checkbox" ${cfg.useSkills!==false?'checked':''}> Tự thi triển kỹ năng</span></label><label><span><input id="auto-empty" type="checkbox" ${cfg.stopNoPotion?'checked':''}> Dừng khi dùng hết đan đã chọn</span></label></div><p class="muted">Đan tiêu hao từ túi khi sử dụng; hồi 40% HP, hồi chiêu 10 giây. Phiên kết thúc tối đa 4 giờ, kể cả offline. Tử vong mất 10% tu vi đang tích lũy.</p><button class="primary full" data-action="confirm-auto">Bắt đầu săn</button>`)}
function petCombatView(){const p=preparePet(s),st=petStats(p),bonus=petContribution(s);return `<div class="pet-combat"><strong>${esc(p.name)} · Lv.${p.level} ${p.hp<=0?'· Kiệt sức':''}</strong><span>HP ${format(p.hp)}/${st.hp} · MP ${format(p.mp)}/${st.mp}</span><span>EXP riêng ${p.exp}/50 · ATK ${st.attack} · DEF ${st.defense}</span><span class="pet-bonus">Cộng cho nhân vật: +${bonus.hp} HP · +${bonus.attack} ATK · +${bonus.defense} DEF</span></div>`}
function pets(){const p=preparePet(s),fox=d.combat.monsters.find(x=>x.id==='monster_005_2');return `<div class="card pet-card compact-pet">${art(fox,'pet-art')}<h3>Linh Hồ</h3>${p?`<span class="badge">Lv.${p.level} · ${p.active?'Tham chiến':'Đang nghỉ'}</span>${petCombatView()}<p class="muted">Khi tham chiến và còn HP, cộng HP, ATK, DEF vào nhân vật. Nhận riêng 20% EXP quái, không trừ tu vi của chủ nhân. Hồi HP/MP ngoài chiến đấu.</p><div class="row">${btn(p.active?'Cho nghỉ':'Tham chiến','pet-toggle','outline')}${btn('Cho ăn · 5 thảo','pet-feed','outline')}</div>${btn('Huấn luyện','pet-train','outline full')}<div class="pet-skill-placeholder">Kỹ năng riêng · Chưa mở</div>`:`<p class="muted">Kết duyên để cùng chiến đấu.</p>${btn('Kết duyên · 300 ◆','pet-adopt','gold-button full')}`}</div>`}
function menu(){return head('Hành trang đạo hữu','Mọi thứ cần cho hành trình của bạn.','MENU')+`<div class="menu-grid">${[['encyclopedia','book','Bách khoa toàn thư','Trang bị, vật phẩm & trang phục'],['bag','bag','Túi đồ','Trang bị, nguyên liệu & đan dược'],['quests','book','Nhiệm vụ','Tiến độ và phần thưởng'],['reports','clock','Báo cáo','Tổng kết các hoạt động đã xong'],['market','coin','Phường thị','Mua bán với NPC']].map(([page,i,n,sub])=>`<button class="menu-item" data-tab="${page}">${icon(i)}<span><strong>${n}${page==='reports'?` <b id="report-count" class="report-count">${s.reports.filter(r=>!r.read).length||''}</b>`:''}</strong><small>${sub}</small></span><b>›</b></button>`).join('')}</div>${btn('Cài đặt & bản lưu','settings','outline full','style="margin-top:18px"')}`}
function reportsPage(){return head('Báo cáo hoạt động','Chỉ ghi nhận tổng kết khi hoàn thành, dừng hoặc chuyển hoạt động.','LỊCH SỬ')+(s.reports.length?s.reports.map(reportCard).join(''):'<div class="empty">Chưa có hoạt động nào hoàn thành.</div>')}
const itemIcon=id=>{const e=d.equipment.items.find(x=>x.id===id),i=d.items.items.find(x=>x.id===id);return e?(e.slot==='weapon'?'sword':'shield'):id==='potion'||i?.category?.endsWith('_pill')?'flask':i?.category==='herb'?'leaf':i?.category==='ore'?'shield':'star'};
const categories={herb:'Linh thảo',ore:'Khoáng vật',soul:'Tinh hồn',cultivation_pill:'Đan tu vi',breakthrough_pill:'Đan đột phá',attack_pill:'Đan công',hp_pill:'Đan HP',defense_pill:'Đan thủ',processed_material:'Tinh luyện',talisman:'Phù lục',gem:'Bảo thạch',breakthrough_material:'Vật liệu đột phá',utility:'Tiện ích'};
const slotNames={weapon:'Vũ khí',head:'Nón',chest:'Áo',pants:'Quần',feet:'Giày',pendant:'Ngọc bội'};
const romanTier=n=>['Dùng chung','I','II','III','IV','V','VI','VII','VIII','IX'][n]||String(n);
function tierOptions(selected,shared=false){return `<option value="">Tất cả bậc</option>${shared?`<option value="0" ${selected==='0'?'selected':''}>Dùng chung</option>`:''}`+d.cultivation.realms.map((r,i)=>`<option value="${i+1}" ${String(i+1)===selected?'selected':''}>Bậc ${romanTier(i+1)} · ${r.name}</option>`).join('')}
function qualityOptions(selected,all=true){return (all?'<option value="">Tất cả phẩm</option>':'')+Object.entries(qualities).map(([id,q])=>`<option value="${id}" ${selected===id?'selected':''}>${q.name}</option>`).join('')}
function itemTierLabel(id){const e=gearTemplate(s,id,d),i=d.items.items.find(i=>i.id===id),tier=e?.tier??i?.tier??0;return tier?'Bậc '+romanTier(tier):'Dùng chung'}
function affixHTML(affixes){return `<div class="affix-list">${affixes.map(a=>`<div><span>${statInfo[a.stat].name}</span><b>+${statText(a.stat,a.value)}</b></div>`).join('')}</div>`}
function gearCatalog(){return head('Bách khoa toàn thư','9 bộ · 54 món · mỗi bậc một bộ','TRA CỨU')+encyclopediaTabs()+qualityLegend()+`<div class="catalog-filters gear-filters"><input id="gear-search" type="search" placeholder="Tên trang bị hoặc bộ…" value="${esc(gearSearch)}"><select id="gear-tier">${tierOptions(gearTier)}</select><select id="gear-slot"><option value="">Tất cả vị trí</option>${Object.entries(slotNames).map(([id,name])=>`<option value="${id}" ${gearSlot===id?'selected':''}>${name}</option>`).join('')}</select><label>Phẩm xem trước<select id="gear-preview-quality">${qualityOptions(gearPreviewQuality,false)}</select></label></div><p class="muted">Tra cứu mẫu không nhận thêm trang bị. Chỉ số minh họa theo phẩm; đồ nhận mới có roll riêng và lưu cố định.</p><div id="gear-catalog-results">${gearCatalogResults()}</div>`}
function gearSample(id){let seed=[...id+gearPreviewQuality].reduce((n,c)=>(n*31+c.charCodeAt(0))>>>0,7);return rollGear(d,id,gearPreviewQuality,()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296})}
function catalogPrimaryStat(e){const a=gearRollRanges(d,e.id,gearPreviewQuality)[0];return statInfo[a.stat].name+' +'+statText(a.stat,a.min)+(a.min!==a.max?' ~ '+statText(a.stat,a.max):'')}
function gearCatalogResults(){const all=d.equipment.items.filter(e=>(!gearTier||e.tier===+gearTier)&&(!gearSlot||e.slot===gearSlot)&&(e.display_name+' '+d.equipment.sets.find(set=>set.id===e.set_id)?.name).toLocaleLowerCase('vi').includes(gearSearch.toLocaleLowerCase('vi'))),start=gearPage*24,items=all.slice(start,start+24),q=qualities[gearPreviewQuality];return `<p class="muted">${all.length} mẫu trang bị · ${Math.min(start+1,all.length)}–${Math.min(start+24,all.length)}</p><div class="catalog-list equipment-catalog">${items.map(e=>`<button data-gear-preview="${e.id}" data-quality="${gearPreviewQuality}">${itemArt(e.id)}<span><strong class="quality-text">${esc(e.display_name)}</strong><small>Bậc ${romanTier(e.tier)} · ${slotNames[e.slot]} · ${qualities[gearPreviewQuality].name}</small><small>${q.minLines===q.maxLines?q.minLines:q.minLines+'–'+q.maxLines} thuộc tính</small><small class="quality-text">${catalogPrimaryStat(e)}</small><small>Xem dòng phụ & khoảng min ~ max →</small></span></button>`).join('')}</div>${!all.length?'<div class="empty">Không có mẫu phù hợp bộ lọc.</div>':''}<div class="row catalog-pages"><button data-gear-page="${gearPage-1}" ${gearPage===0?'disabled':''}>← Trước</button><span>${gearPage+1}/${Math.max(1,Math.ceil(all.length/24))}</span><button data-gear-page="${gearPage+1}" ${start+24>=all.length?'disabled':''}>Sau →</button></div>`}
function gearStats(e,affixes){const first={weapon:'attack',head:'mp',chest:'hp',pants:'defense',feet:'speed',pendant:'dodge'}[e.slot];return affixHTML(affixes.filter(a=>a.value!==0).sort((a,b)=>(b.stat===first)-(a.stat===first)))}
function gearCard(e,id,quality,affixes,showSet=true){const key={weapon:'attack',head:'mp',chest:'hp',pants:'defense',feet:'speed',pendant:'dodge'}[e.slot],visible=affixes.filter(a=>a.value!==0),main=visible.find(a=>a.base)||visible.find(a=>a.stat===key)||visible[0]||{stat:key,value:0},secondary=visible.filter(a=>a!==main);return `<section class="gear-detail" data-quality="${quality}"><div class="gear-hero"><p class="gear-type">${slotNames[e.slot]} · ${qualities[quality].name}</p><div class="gear-primary"><span>${statInfo[main.stat].name}</span><b>+${statText(main.stat,main.value)}</b></div><div class="gear-hero-art">${itemArt(id)}</div></div><div class="gear-sheet"><p class="gear-rank">${gearRank(e)}</p>${gearStats(e,secondary)}${showSet?gearSetAttributes(e):''}`}
function gearSetAttributes(e){const set=d.equipment.sets.find(set=>set.id===e.set_id),count=Object.values(s.equipment).filter(id=>gearTemplate(s,id,d)?.set_id===e.set_id).length;return `<section class="gear-set"><h3>Thuộc tính bộ</h3><p>${esc((set?.name||'').replace(/\s+Trang$/,''))} <span class="muted">(${count}/6)</span></p><small class="muted">Hiệu ứng bộ chưa mở.</small></section>`}
function gearRank(e){return `Bậc ${romanTier(e.tier)} · ${d.cultivation.realms[e.tier-1].name} Kỳ`}
function gearPreview(id){const e=d.equipment.items.find(e=>e.id===id),g=gearSample(id);if(!e||!g)return;const m=d.world.locations.find(m=>m.id===e.map_id);modal(e.display_name,`${gearCard(e,id,g.quality,g.affixes.filter(a=>a.base),false)}${gearRangeHTML(e,g.quality)}${gearSetAttributes(e)}<p class="gear-sample-note">${qualities[g.quality].minLines}–${qualities[g.quality].maxLines} dòng tổng cộng, gồm 1 dòng gốc. Dòng phụ chọn ngẫu nhiên, không trùng dòng chỉ số.</p><button class="outline full" data-forge-item="${id}">Xem công thức chế tạo →</button><details class="gear-source"><summary>Nguồn trang bị</summary><p>${esc(d.cultivation.realms[e.tier-1].name)} · nhận tại các map cùng bậc khi săn quái/Boss hoặc luyện khí.</p><p class="muted">Mỗi món nhận mới có chỉ số ngẫu nhiên và được lưu riêng.</p><button class="outline full" data-location="${d.world.locations.indexOf(m)}">Xem địa điểm →</button></details></div></section>`,g.quality)}
function gearRangeHTML(e,quality){const all=gearRollRanges(d,e.id,quality);return `<section class="roll-ranges"><h3>Các dòng phụ có thể ra</h3><p class="muted">Khoảng min ~ max theo ${qualities[quality].name}.</p>${all.filter(a=>!a.base).map(a=>`<div class="range-row"><span>${statInfo[a.stat].name}</span><b>+${statText(a.stat,a.min)} ~ +${statText(a.stat,a.max)}</b></div>`).join('')}</section>`}
function bagEntries(){return bagTab==='equipment'?s.owned.filter(id=>{const e=gearTemplate(s,id,d);return e&&!Object.values(s.equipment).includes(id)&&(!ownedTier||e.tier===+ownedTier)&&(!ownedQuality||gearQuality(s,id)===ownedQuality)&&(!ownedSlot||e.slot===ownedSlot)}).map(id=>[id,1]):Object.entries(s.bag).filter(([id,n])=>{const i=inventoryItem(id,d);return n>0&&i&&(!bagItemTier||i.tier===+bagItemTier)&&(!bagItemQuality||(i.quality||'white')===bagItemQuality)&&(!bagItemCategory||i.category===bagItemCategory)&&i.name.toLocaleLowerCase('vi').includes(bagItemSearch.toLocaleLowerCase('vi'))})}
function saleSelection(q){return bagEntries().filter(([id])=>bagTab==='equipment'?gearQuality(s,id)===q:(inventoryItem(id,d)?.quality||'white')===q&&itemSellPrice(id,d)>0)}
function bulkSaleControls(){const count=(bagTab==='equipment'?[ownedTier,ownedQuality,ownedSlot]:[bagItemTier,bagItemQuality,bagItemCategory,bagItemSearch]).filter(Boolean).length;return `<div class="inventory-tools">${btn('Lọc'+(count?' ('+count+')':''),'bag-filters','outline')}${btn('Bán nhanh','quick-sale','outline')}</div>`}
function bagFilters(){const gear=bagTab==='equipment';modal(gear?'Lọc trang bị':'Lọc vật phẩm',`<div class="filter-dialog"><label>Bậc<select id="bag-filter-tier">${tierOptions(gear?ownedTier:bagItemTier,!gear)}</select></label><label>Phẩm chất<select id="bag-filter-quality">${qualityOptions(gear?ownedQuality:bagItemQuality)}</select></label>${gear?`<label>Vị trí<select id="bag-filter-slot"><option value="">Tất cả vị trí</option>${Object.entries(slotNames).map(([id,n])=>`<option value="${id}" ${ownedSlot===id?'selected':''}>${n}</option>`).join('')}</select></label>`:`<label>Loại<select id="bag-filter-category"><option value="">Tất cả loại</option>${Object.entries(categories).map(([id,n])=>`<option value="${id}" ${bagItemCategory===id?'selected':''}>${n}</option>`).join('')}</select></label><label>Tên vật phẩm<input id="bag-filter-search" type="search" value="${esc(bagItemSearch)}"></label>`}</div><div class="row">${btn('Bỏ lọc','clear-bag-filters','outline')}${btn('Áp dụng','apply-bag-filters','primary')}</div>`)}
function quickSale(){modal('Bán đồ nhanh',`<p>Tích chọn một hoặc nhiều phẩm chất trong bộ lọc hiện tại. Giữ lại đồ đang mặc và vật phẩm không thể bán.</p><fieldset class="sale-checklist"><legend>Phẩm chất cần bán</legend>${Object.entries(qualities).map(([q,v])=>{const count=saleSelection(q).reduce((n,e)=>n+e[1],0);return `<label data-quality="${q}"><input id="sell-quality-${q}" type="checkbox" ${count?'':'disabled'}><span class="quality-text">${v.name}</span><b>${count} món</b></label>`}).join('')}</fieldset>${btn('Tiếp tục','bulk-sale','primary full','style="margin-top:12px"')}`)}

function forgingPage(){return head('Luyện khí','54 công thức · chọn món cần chế tạo','ĐỒ PHỔ')+activity()+`<div class="catalog-filters"><select id="forge-tier">${tierOptions(forgeTier)}</select><select id="forge-slot"><option value="">Tất cả vị trí</option>${Object.entries(slotNames).map(([id,n])=>`<option value="${id}" ${forgeSlot===id?'selected':''}>${n}</option>`).join('')}</select><label>Số mẻ<input id="forge-count" type="number" min="1" max="100" value="${forgeCount}"></label></div><p class="muted">Chọn công thức, xem nguyên liệu và phí trước khi rèn. Mỗi món có phẩm và chỉ số riêng.</p><div id="forge-results">${forgingResults()}</div>`}
function forgingResults(){const recipes=d.items.recipes.filter(r=>{const e=gearTemplate(s,r.output_id,d);return r.discipline==='forging'&&e&&(!forgeTier||e.tier===+forgeTier)&&(!forgeSlot||e.slot===forgeSlot)});return `<p class="muted">${recipes.length} công thức trang bị</p>`+recipes.map(r=>recipeView(r,true)).join('')+`<details class="forge-materials"><summary>Tinh luyện nguyên liệu</summary>${d.items.recipes.filter(r=>r.discipline==='forging'&&!gearTemplate(s,r.output_id,d)&&(!forgeTier||recipeOutput(r,d)?.tier===+forgeTier)).map(r=>recipeView(r,true)).join('')}</details>`}
function ownedFilters(){return `<button class="outline full" data-tab="encyclopedia">Bách khoa toàn thư →</button>`}

function itemCatalog(){return `<div class="catalog-filters"><input id="catalog-search" type="search" placeholder="Tìm tên vật phẩm…" value="${esc(catalogSearch)}"><select id="catalog-category"><option value="">Tất cả loại</option>${Object.entries(categories).map(([id,n])=>`<option value="${id}" ${catalogCategory===id?'selected':''}>${n}</option>`).join('')}</select><select id="item-tier">${tierOptions(itemTier,true)}</select><select id="item-quality">${qualityOptions(itemQuality)}</select></div><div id="catalog-results">${catalogResults()}</div>`}
function encyclopediaTabs(){return `<div class="tabs">${[['equipment','Trang bị'],['items','Vật phẩm'],['wardrobe','Trang phục']].map(([id,n])=>`<button data-encyclopedia="${id}" class="${encyclopediaTab===id?'active':''}">${n}</button>`).join('')}</div>`}
function encyclopedia(){return encyclopediaTab==='equipment'?gearCatalog():head('Bách khoa toàn thư','Tra cứu trang bị, vật phẩm và trang phục','TRA CỨU')+encyclopediaTabs()+(encyclopediaTab==='items'?itemCatalog():wardrobe())}
function bag(){const entries=bagEntries();return head('Túi càn khôn','','HÀNH TRANG')+ownedFilters()+`<div class="tabs inventory-tabs">${[['equipment','Trang bị'],['items','Vật phẩm']].map(([id,n])=>`<button data-bag="${id}" class="${bagTab===id?'active':''}">${n}</button>`).join('')}</div>`+bulkSaleControls()+`<div class="inventory-grid">${entries.map(([id,n])=>`<button class="inventory-slot ${Object.values(s.equipment).includes(id)?'is-worn':''}" data-item="${id}" ${qualityAttribute(id)} aria-label="${esc(itemName(id))}, ${itemTierLabel(id)}, ${gearTemplate(s,id,d)?qualities[gearQuality(s,id)].name:qualities[d.items.items.find(i=>i.id===id)?.quality||'white'].name}, số lượng ${n}" title="${esc(itemName(id))} · ${itemTierLabel(id)}">${itemArt(id)}<span class="inventory-tier">${itemTierLabel(id).replace('Bậc ','')}</span><b>×${n}</b>${inventoryStat(id)}${Object.values(s.equipment).includes(id)?'<small aria-label="Đang mặc">✓</small>':''}</button>`).join('')}</div>${entries.length?'':'<div class="card muted">Không có đồ phù hợp. Tra cứu nguồn kiếm trong Bách khoa toàn thư.</div>'}`}
function catalogResults(){const all=d.items.items.filter(i=>(!catalogCategory||i.category===catalogCategory)&&(!itemTier||i.tier===+itemTier)&&(!itemQuality||i.quality===itemQuality)&&i.name.toLocaleLowerCase('vi').includes(catalogSearch.toLocaleLowerCase('vi'))),start=catalogPage*24,items=all.slice(start,start+24);return `<p class="muted">${all.length} vật phẩm · ${Math.min(start+1,all.length)}–${Math.min(start+24,all.length)}</p><div class="catalog-list">${items.map(i=>`<button data-item="${i.id}" ${qualityAttribute(i.id)}>${itemArt(i.id)}<span><strong class="quality-text">${esc(i.name)}</strong><small>${itemTierLabel(i.id)} · ${qualities[i.quality||'white'].name}<br>${categories[i.category]} · Có ${s.bag[i.id]||0}</small></span></button>`).join('')}</div><div class="row catalog-pages"><button data-catalog-page="${catalogPage-1}" ${catalogPage===0?'disabled':''}>← Trước</button><span>${catalogPage+1}/${Math.max(1,Math.ceil(all.length/24))}</span><button data-catalog-page="${catalogPage+1}" ${start+24>=all.length?'disabled':''}>Sau →</button></div>`}
function itemEffect(i){if(!i)return '';const value=format(+i.value);return {cultivation_pill:`+${value} tu vi, tối đa 10 đan tu vi/ngày (giờ Việt Nam). Không vượt thanh tu vi hiện tại.`,attack_pill:`+${value} ATK vĩnh viễn. Đã dùng ${s.pillUsed?.[i.id]||0}/30 viên.`,hp_pill:`+${value} HP tối đa vĩnh viễn, không phải thuốc hồi máu. Đã dùng ${s.pillUsed?.[i.id]||0}/30 viên.`,defense_pill:`+${value} DEF vĩnh viễn. Đã dùng ${s.pillUsed?.[i.id]||0}/30 viên.`,breakthrough_pill:'Đan hỗ trợ xác suất đột phá; công dụng chờ hệ thống đột phá chính thức.',talisman:'Phù lục chiến đấu: hiệu ứng và nguồn kiếm chưa mở.',gem:'Bảo thạch: chờ tính năng khảm trang bị.',breakthrough_material:'Nguyên liệu đột phá; chưa tiêu hao trong bản đột phá thử nghiệm.',processed_material:'Nguyên liệu tinh luyện dùng trong các công thức dưới đây.'}[i.category]||''}
function slotDetails(slot){const options=s.owned.filter(id=>gearTemplate(s,id,d)?.slot===slot);modal('Chọn trang bị',options.length?options.map(id=>`<button class="replacement full outline" data-item="${id}" ${qualityAttribute(id)}>${itemArt(id)}<span class="quality-text">${esc(itemName(id))} · ${itemTierLabel(id)}</span></button>`).join(''):'<p class="muted">Chưa có món phù hợp trong túi.</p>')}
function itemCard(i,id){const quality=i?.quality||'white',category=i?.category||'recovery',tier=i?.tier||0,meta={cultivation_pill:['Tu vi','+'+format(+i?.value)],attack_pill:['ATK vĩnh viễn','+'+format(+i?.value)],hp_pill:['HP tối đa','+'+format(+i?.value)],defense_pill:['DEF vĩnh viễn','+'+format(+i?.value)],recovery:['Hồi HP','40%']}[category]||['Đang có','×'+format(s.bag[id]||0)];return `<section class="gear-detail item-detail" data-quality="${quality}"><div class="gear-hero"><p class="gear-type">${esc(categories[category]||'Thuốc hồi phục')} · ${qualities[quality].name}</p><div class="gear-primary"><span>${meta[0]}</span><b>${meta[1]}</b></div><div class="gear-hero-art">${itemArt(id)}</div></div><div class="gear-sheet"><p class="gear-rank">${tier?'Bậc '+romanTier(tier)+' · '+d.cultivation.realms[tier-1].name+' Kỳ':'Dùng chung'}</p><div class="row item-stock"><span>Đang sở hữu</span><b>${format(s.bag[id]||0)}</b></div><section class="item-use"><h3>Công dụng</h3><p>${id==='potion'?'Hồi 40% HP tối đa. Hồi chiêu 10 giây.':itemEffect(i)||({herb:'Linh thảo dùng để tinh luyện Linh Dịch và luyện đan.',ore:'Khoáng vật dùng để luyện khí và tinh luyện nguyên liệu.',soul:'Tinh hồn dùng trong các công thức phù hợp.'}[category]||'Vật liệu cho các công thức tương ứng.')}</p></section>`}
function itemDetails(id){const e=gearTemplate(s,id,d);if(e){const worn=s.equipment[e.slot]===id,quality=gearQuality(s,id),comparison=gearComparison(s,id,d),m=d.world.locations.find(m=>m.id===e.map_id),owned=s.owned.includes(id),affixes=gearAffixes(s,id,d);modal(itemName(id),`${gearCard(e,id,quality,affixes)}${!worn&&comparison.current?`<div class="gear-compare"><p>So sánh với món đang mặc</p>${gearDelta(id)}</div>`:''}${owned?`<div class="detail-actions">${worn?`<button class="primary" data-slot="${e.slot}">Thay thế</button><button class="outline" data-unequip="${e.slot}">Tháo</button>`:`<button class="primary full" data-equip="${id}" ${canEquip(s,e,d)?'':'disabled'}>${s.equipment[e.slot]?'Thay thế trang bị':'Trang bị'}</button>`}</div>`:''}${owned?`<button class="outline full sell-gear" data-sell-gear="${id}" ${worn?'disabled':''}>Bán · ${format(equipmentSellPrice(s,id,d))} ◆</button>${worn?'<p class="muted">Tháo trang bị trước khi bán.</p>':''}`:''}${canEquip(s,e,d)?'':`<p class="stat-down">Yêu cầu ${m.requirement_label}.</p>`}<details class="gear-source"><summary>Nguồn trang bị</summary><p>${esc(d.cultivation.realms[e.tier-1].name)} · nhận tại các map cùng bậc khi săn quái/Boss hoặc luyện khí.</p>${s.gearInstances?.[id]?.legacy?'<p class="muted">Đồ cũ giữ nguyên chỉ số.</p>':''}</details></div></section>`,quality);return}const i=d.items.items.find(x=>x.id===id);if(id!=='potion'&&!i)return;const sourceBoss=d.combat.bosses.find(b=>b.id===i?.source_boss_id),mapIndex=d.world.locations.findIndex(m=>m.id===(i?.source_map_id||sourceBoss?.map_id)),uses=d.items.recipes.filter(r=>r.inputs.some(x=>x.item_id===id)),asOutput=d.items.recipes.filter(r=>r.output_id===id),alchemy=[...asOutput,...uses].some(r=>r.discipline==='alchemy');modal(itemName(id),itemCard(i,id)+`${['cultivation_pill','attack_pill','hp_pill','defense_pill'].includes(i?.category)?`<button class="primary full" data-use-pill="${id}" ${pillStatus(s,id,d)?'disabled':''}>${pillStatus(s,id,d)||'Dùng 1 viên'}</button>`:''}${id==='potion'?btn('Sử dụng','item-heal','primary full'):''}<section class="item-sources"><h3>Cách kiếm</h3><p>${id==='potion'?'Luyện từ 5 Hoàng Tinh Thảo + 10 linh thạch; 8 giây/mẻ. Có bán tại Phường thị.':sourceBoss?'Boss '+esc(sourceBoss.name)+(i.category==='soul'?' · có thể nhận sau chiến thắng.':' · nguồn này chưa mở trong bản thử.'):mapIndex>=0?(i.category==='herb'?'Hái linh thảo tại ':'Khai khoáng tại ')+esc(d.world.locations[mapIndex].name):asOutput.length?'Chế tạo theo công thức bên dưới.':'Nguồn kiếm chưa được mở trong bản thử nghiệm.'}</p>${mapIndex>=0?`<button class="outline full" data-location="${mapIndex}">Xem địa điểm →</button>`:''}</section>${asOutput.length?`<h3 class="item-section-title">Công thức chế tạo</h3>${asOutput.map(r=>recipeView(r)).join('')}`:''}${alchemy?`<button class="outline full" data-alchemy-item="${id}">Xem công thức luyện đan liên quan →</button>`:''}${uses.length?`<details class="item-recipes"><summary>Dùng trong ${uses.length} công thức</summary>${uses.slice(0,4).map(r=>recipeView(r)).join('')}${uses.length>4?'<p class="muted">Chỉ hiện 4 công thức đầu. Mở sổ đan phương để lọc công thức luyện đan liên quan.</p>':''}</details>`:''}${(id==='potion'||i?.tradeable)&&s.bag[id]>0?`<div class="sell-row"><label>Số lượng bán<input id="sell-count" type="number" min="1" max="${s.bag[id]||0}" value="1"></label><button class="outline" data-sell-item="${id}">Bán · ${sellPrice(id)} ◆/cái</button></div>`:''}</div></section>`,i?.quality||'white')}

const sellPrice=id=>id==='potion'?25:d.items.items.find(i=>i.id===id)?.category==='soul'?10:3;
function recipeView(r,batch=false){const count=batch?(r.discipline==='forging'?forgeCount:alchemyCount):1,valid=Number.isInteger(count)&&count>=1&&count<=100,n=valid?count:1,status=recipeStatus(s,r,d,count),out=recipeOutput(r,d),quality=out?.quality||'white';return `<section class="recipe-card" data-quality="${quality}"><button class="recipe-product" ${out?.slot?'data-gear-preview':'data-item'}="${r.output_id}">${itemArt(r.output_id)}<span><strong>${esc(itemName(r.output_id))}</strong><small>${out?.tier?'Bậc '+romanTier(out.tier):'Dùng chung'} · ${r.output_count*n} ${out?.slot?'món':out?.category==='processed_material'?'phần':'viên'} / ${n} mẻ</small></span></button><div class="recipe-inputs">${r.inputs.map(i=>{const needed=i.quantity*n,have=s.bag[i.item_id]||0;return `<button data-item="${i.item_id}" class="ingredient ${have>=needed?'enough':'missing'}"><span>${esc(itemName(i.item_id))}</span><b>${have}/${needed}</b></button>`}).join('')}</div><div class="recipe-facts"><span>${format(+r.stone_cost*n)} linh thạch</span><span>${r.duration_seconds*n} giây</span><span>${r.base_success_bp/100}% / mẻ</span></div><button class="${status?'outline':'gold-button'} full" data-recipe="${r.id}" ${batch?'data-recipe-batch="yes"':''} ${status?'disabled':''}>${esc(status||((r.discipline==='alchemy'?'Luyện ':'Chế tạo ')+n+' mẻ'))}</button></section>`}

const quests=[['Sơ nhập tiên môn','Bắt đầu hành trình tu tiên',200],['Tiên lộ sơ khai','Đánh bại 3 yêu thú',300],['Linh thảo đầu tay','Thu thập 5 linh thảo',200],['Phá kén thành tiên','Đột phá tầng đầu tiên',500],['Trừ ma vệ đạo','Đánh bại Boss đầu tiên',800]];
function questView(){return head('Tiên lộ ký','Mỗi bước chân đều có hồi đáp.','NHIỆM VỤ')+`<div class="notice">Nhiệm vụ tân thủ · ${s.claimed.length}/5 đã nhận thưởng</div>`+quests.map(([n,desc,reward],i)=>{const done=s.claimed.includes(i),ready=questReady(s,i);return `<div class="card"><div class="row"><h3>${n}</h3><span class="badge">${done?'Đã nhận':ready?'Hoàn thành':'Đang làm'}</span></div><p class="muted">${desc}</p><div class="row" style="margin-top:12px"><span style="color:var(--gold)">◆ ${reward} · 1 Hồi Xuân Đan</span><button data-claim="${i}" class="${ready&&!done?'gold-button':''}" ${!ready||done?'disabled':''}>${done?'Đã nhận':'Nhận thưởng'}</button></div></div>`}).join('')}
function skillView(){const arts=d.arts.arts.filter(x=>d.cultivation.realms.findIndex(r=>r.id===x.cultivation_id)<=s.realm);return head('Tàng Kinh Các','5 ô dùng lần lượt; mỗi lượt dùng 1 kỹ năng hoặc đánh thường, có tiêu hao MP.','CÔNG PHÁP')+`<div class="card">${arts.map(a=>{const learned=s.skills[a.id]||0,active=s.equippedSkills.includes(a.id);return `<div class="skill-row"><div><strong>${a.name}</strong><p class="muted">Lv. ${learned} · ${+a.direct_attack_coefficient>0?'Sát thương ×'+(+a.direct_attack_coefficient*(1+.05*Math.max(0,learned-1))).toFixed(2):'Hồi 8% HP + lá chắn 8% HP'} · ${a.cooldown_seconds}s · ${format(skillCost(a))} MP</p></div><div class="row"><button class="outline" data-skill="${a.id}">${learned?'Nâng cấp':'Lĩnh ngộ'} · ${100*(learned+1)} ◆</button>${learned?`<button class="${active?'primary':'outline'}" data-equip-skill="${a.id}">${active?'Tháo':'Trang bị'}</button>${active?`<button class="text-button" data-skill-move="${a.id}" data-shift="-1" aria-label="Đưa ${esc(a.name)} lên trước">↑</button><button class="text-button" data-skill-move="${a.id}" data-shift="1" aria-label="Đưa ${esc(a.name)} ra sau">↓</button>`:''}`:''}</div></div>`}).join('')}</div><p class="muted">Mỗi cấp cộng 8 công kích và tăng 5% hệ số kỹ năng gây sát thương. Kỹ năng hỗ trợ dùng hiệu ứng thử nghiệm như mô tả trên.</p>`}
function market(){return head('Phường thị','Dừng chân đổi vật, tiếp bước tiên lộ.','CỬA HÀNG DEMO')+`<div class="notice">Cửa hàng NPC dùng linh thạch trong bản chơi thử. Chưa có chợ giao dịch giữa người chơi.</div><div class="card"><div class="list-row"><span class="item-icon">${icon('flask')}</span><div class="list-info"><strong>Hồi Xuân Đan</strong><p>Hồi 40% HP · ◆ 50 / viên</p></div>${btn('Mua 1','buy-potion','outline')}</div><div class="list-row"><span class="item-icon">${icon('leaf')}</span><div class="list-info"><strong>Hoàng Tinh Thảo × 5</strong><p>Nguyên liệu luyện đan · ◆ 30</p></div>${btn('Mua 5','buy-herb','outline')}</div></div><div class="card"><h3>Bán linh thảo</h3><p class="muted">Bán 5 Hoàng Tinh Thảo để nhận 15 linh thạch.</p>${btn('Bán 5 · +15 ◆','sell-herb','full outline')}</div>`}
const pages={encyclopedia,gearCatalog,home,cultivation,combatStats,profession:professionPage,world:worldView,location:locationPage,battle,pets,menu,reports:reportsPage,bag,quests:questView,skills:skillView,market};
function render(){syncBattleEffects();info();$('#main').innerHTML=pages[tab]();const active=['home','cultivation','battle','world'].includes(tab)?tab:tab==='location'?'world':tab==='pets'?'home':['profession','combatStats','skills'].includes(tab)?'cultivation':'menu';$('#bottom-nav').innerHTML=navs.map(([t,i,n])=>`<button data-tab="${t}" class="${t===active?'active':''}" ${t===active?'aria-current="page"':''}>${icon(i)}<span>${n}</span></button>`).join('');if(tab==='world')applyMapView()}
function go(t){if(!pages[t])return;if(t==='world'){const m=tab==='location'?d.world.locations[selectedMap]:current();world=mapWorld(m);window.scrollTo({top:0,behavior:'instant'})}tab=t;if(t==='reports')s.reports.forEach(r=>r.read=true);render();window.scrollTo({top:0,behavior:'instant'})}
function modal(title,html,quality=null){$('#modal').classList.toggle('equipment-modal',!!quality);$('#modal-title').textContent=title;$('#modal-title').classList.toggle('quality-text',!!quality);if(quality)$('#modal-title').setAttribute?.('data-quality',quality);else $('#modal-title').removeAttribute?.('data-quality');$('#modal-content').innerHTML=html;if(!$('#modal').open)$('#modal').showModal()}
function maybeReport(){if($('#modal').open)return;const r=s.reports.find(r=>!r.read);if(!r)return;r.read=true;save();info();modal('Tổng kết hoạt động',reportCard(r)+`<div class="row"><button class="outline" data-action="close">Đóng</button><button class="primary" data-action="all-reports">Tất cả báo cáo →</button></div>`)}
function confirmChange(label,callback){if(!s.session)return false;pendingAction=callback;modal('Xác nhận đổi hành động',`<p>Đang ${names[s.activity]||'hoạt động'}. Chuyển sang <b>${esc(label)}</b>?</p><p class="muted">Hoạt động hiện tại sẽ dừng và được tổng kết. Phần thưởng đã nhận được giữ lại.${s.activity==='travel'?' Bạn ở lại điểm xuất phát; phí đã dùng không hoàn lại.':''}</p><div class="row">${btn('Tiếp tục việc hiện tại','cancel-change','outline')}${btn('Xác nhận','confirm-change','primary')}</div>`);return true}
function beginRecipe(id,count,approved=false){const r=d.items.recipes.find(r=>r.id===id),reason=recipeStatus(s,r,d,count);if(reason){toast(reason);return false}if(!approved&&confirmChange('Luyện chế '+count+' mẻ',()=>beginRecipe(id,count,true)))return false;if(!startRecipe(s,id,d,count))return false;save();if($('#modal').open)$('#modal').close();if(tab==='profession'&&['alchemy','forging'].includes(profession))render();else go('home');return true}
function beginJourney(to,mode,toBattle,approved=false){const plan=journeyPlan({...s,activity:null},d,to,mode);if(!plan.ok){toast(plan.reason);return false}if(!approved&&confirmChange('Di chuyển đến '+d.world.locations[to].name,()=>beginJourney(to,mode,toBattle,true)))return false;if(s.activity==='travel')finish(s,'Đã chuyển hoạt động');const result=startTravel(s,d,to,mode);if(!result.ok){toast(result.reason);return false}if(toBattle)s.battleDestination=to;else delete s.battleDestination;$('#modal').close();save();go('home');return true}
function stopActivity(approved=false){if(!s.session)return;if(!approved&&confirmChange('Dừng và nghỉ ngơi',()=>stopActivity(true)))return;finish(s,'Đã dừng theo yêu cầu');save();$('#modal').close();render();maybeReport()}
function start(a,options={},approved=false){if(a==='craft'&&((s.bag.herb_001||0)<5||s.stones<10)){toast('Cần 5 Hoàng Tinh Thảo và 10 linh thạch.');return false}if(a==='forge'&&((s.bag[resource(d,s.map,'ore').id]||0)<3||s.stones<80)){toast('Cần 3 khoáng vật tại đây và 80 linh thạch.');return false}if(['fight','boss'].includes(a)&&s.hp<stats(s,d).hp*.25){toast('Sinh lực thấp. Hãy nghỉ ngơi hoặc dùng đan dược.');return false}if(a==='pettrain'&&!s.pet)return false;
 if(!approved&&confirmChange(names[a],()=>start(a,options,true)))return false;if(options.battleConfig){s.battleSettings=options.battleConfig;options={...options};delete options.battleConfig;}if($('#modal').open)$('#modal').close();setActivity(s,a,options);if(['fight','boss'].includes(a))battleDetails=false;save();if(['fight','boss'].includes(a)){battleMode=a==='boss'?'boss':'normal';go('battle')}else render();maybeReport();return true}
function travel(i,toBattle=false){const m=d.world.locations[i];if(!m)return;if(i===s.map){selectedMap=i;go(toBattle?'battle':'location');return}travelChoice(i,toBattle)}
function settings(){modal('Thiết lập đạo hữu',`<p class="muted">Vạn Đạo v0.21.0 · Tiến trình lưu trên trình duyệt này.</p><label class="setting-label" for="rename">Tên đạo hữu</label><input id="rename" maxlength="24" value="${esc(s.name)}">${btn('Lưu tên','rename','primary full','style="margin-top:10px"')}<label class="setting-label">Bản lưu cá nhân</label>${btn('Xuất bản lưu JSON','export','full')}<label class="setting-label" for="save-import">Nhập bản lưu JSON</label><input type="file" id="save-import" accept=".json,application/json"><p class="muted">Nhập sẽ thay thế tiến trình hiện tại trên máy này.</p><div class="notice">Bản chơi thử cá nhân, chưa có máy chủ MMO. Báo cáo chỉ xuất hiện khi hoạt động kết thúc. Auto chiến đấu tối đa 4 giờ mỗi phiên; hoạt động khác offline tối đa 8 giờ.</div>${btn('Tạo lại nhân vật','reset-confirm','full')}`)}
document.addEventListener('click',ev=>{const el=ev.target.closest('button');if(!el||el.disabled)return;const x=el.dataset;if(mapGesture.suppress&&el.closest?.('.map-viewport')){mapGesture.suppress=false;ev.preventDefault?.();return}
 if(x.gateView!==undefined){if($('#modal').open)$('#modal').close();selectedMap=+x.gateView;go('location');return}
 if(x.gateRoute!==undefined){travelChoice(+x.gateRoute,false,'ascend');return}
 if(x.routeTo!==undefined){beginJourney(+x.routeTo,x.routeMode,x.routeBattle==='yes');return}
 if(x.forgeItem){const e=gearTemplate(s,x.forgeItem,d);if(!e)return;forgeTier=String(e.tier);forgeSlot=e.slot;profession='forging';$('#modal').close();go('profession');return}
 if(x.skillMove){const from=s.equippedSkills.indexOf(x.skillMove),to=from+Number(x.shift);if(from>=0&&to>=0&&to<s.equippedSkills.length){[s.equippedSkills[from],s.equippedSkills[to]]=[s.equippedSkills[to],s.equippedSkills[from]];save();render()}return}
 if(x.skillInfo){skillInfo(x.skillInfo);return}
 if(x.sellGear){const id=x.sellGear;if(!s.owned.includes(id)||Object.values(s.equipment).includes(id)){toast('Tháo trang bị trước khi bán.');return}modal('Bán trang bị?',`<p>Bán ${esc(itemName(id))} để nhận ${format(equipmentSellPrice(s,id,d))} linh thạch?</p><div class="row"><button class="outline" data-item="${id}">Quay lại</button><button class="primary" data-confirm-sell-gear="${id}">Xác nhận bán</button></div>`);return}
 if(x.confirmSellGear){if(!sellEquipment(s,x.confirmSellGear,d)){toast('Không thể bán trang bị này.');return}save();$('#modal').close();render();toast('Đã bán trang bị');return}
 if(x.gearPreview){gearPreview(x.gearPreview);return}
 if(x.gearPage!==undefined){gearPage=Math.max(0,+x.gearPage);$('#gear-catalog-results').innerHTML=gearCatalogResults();return}
 if(x.homeTab){homeTab=x.homeTab;go('home');return}
 if(x.item){itemDetails(x.item);return}
 if(x.slot){slotDetails(x.slot);return}
 if(x.unequip){unequip(s,x.unequip,d);save();render();slotDetails(x.unequip);return}
 if(x.alchemyPage!==undefined){alchemyPageIndex=Math.max(0,+x.alchemyPage);$('#alchemy-results').innerHTML=alchemyResults();return}
 if(x.alchemyItem){alchemyIngredient=x.alchemyItem;alchemyTier='';alchemyCategory='';alchemySearch='';alchemyPageIndex=0;profession='alchemy';$('#modal').close();go('profession');return}
 if(x.itemProfession){$('#modal').close();profession=x.itemProfession;go('profession');return}
 if(x.sellItem){const n=Number($('#sell-count').value);if(!sellItem(s,x.sellItem,n,d)){toast('Số lượng bán không hợp lệ.');return}save();render();itemDetails(x.sellItem);return}
 if(x.recipe){beginRecipe(x.recipe,x.recipeBatch==='yes'?(d.items.recipes.find(r=>r.id===x.recipe)?.discipline==='forging'?forgeCount:alchemyCount):1);return}
 if(x.previewSkin){skinDetails(x.previewSkin);return}
 if(x.wearSkin){if(!wearSkin(s,x.wearSkin,d)){toast('Chưa đủ cảnh giới để mặc trang phục.');return}save();$('#modal').close();render();toast('Đã đổi trang phục');return}
 if(x.mapArt){showMapArt(x.mapArt);return}
 if(x.mapBattle!==undefined){battleMode='normal';travel(+x.mapBattle,true);return}
 if(x.usePill){if(!usePill(s,x.usePill,d))toast(pillStatus(s,x.usePill,d));else toast('Đã sử dụng '+itemName(x.usePill));save();render();itemDetails(x.usePill);return}
 if(x.catalogPage!==undefined){catalogPage=Math.max(0,+x.catalogPage);$('#catalog-results').innerHTML=catalogResults();return}
 if(x.autoFight){autoSetup();return}
 if(x.healThreshold){s.battleSettings.potionThreshold=+x.healThreshold;save();render();return}
 if(x.battleDuration){s.battleSettings.duration=+x.battleDuration;save();render();return}
 if(x.equipSkill){const id=x.equipSkill;if(!s.skills[id])return;const index=s.equippedSkills.indexOf(id);if(index>=0)s.equippedSkills.splice(index,1);else if(s.equippedSkills.length<5)s.equippedSkills.push(id);else{toast('Chỉ trang bị tối đa 5 kỹ năng.');return}save();render();return}
 if(x.tab){if($('#modal').open)$('#modal').close();go(x.tab);return}
 if(x.profession){profession=x.profession;go('profession');return}
 if(x.encyclopedia){encyclopediaTab=x.encyclopedia;go('encyclopedia');return}
 if(x.bag){if(['catalog','wardrobe'].includes(x.bag)){encyclopediaTab=x.bag==='catalog'?'items':'wardrobe';go('encyclopedia')}else{bagTab=x.bag;render()}return}
 if(x.world){world=x.world;render();return}
 if(x.region){if(!worldRegions(d,world).some(r=>r.id===x.region))return;const viewport=$('.map-viewport');mapViews.set(mapViewKey(),focusedMap(d,world,s.map,x.region,viewport.clientWidth||320,viewport.clientHeight||420));applyMapView();return}
 if(x.location!==undefined){if($('#modal').open)$('#modal').close();selectedMap=+x.location;go('location');return}
 if(x.travel!==undefined){travel(+x.travel);return}
 if(x.entity){entityDetails(x.entity);return}
 if(x.resource){resourceDetails(x.resource);return}
 if(x.combatMode){battleMode=x.combatMode;render();return}
 if(x.startEntity){const e=d.combat.monsters.find(e=>e.id===x.startEntity)||d.combat.bosses.find(e=>e.id===x.startEntity);if(!e||e.map_id!==current().id)return;if(e.id.startsWith('boss_'))start('boss',{target:e.id});else autoSetup();return}
 if(x.startResource){const r=d.items.items.find(r=>r.id===x.startResource);if(!r||r.source_map_id!==current().id)return;start(r.category==='herb'?'gather':'mine');return}
 if(x.begin){const input=$('#plan-count'),goal=tab==='profession'?Math.max(1,Math.min(x.begin==='cultivate'?28800:1000,Math.floor(Number(input?.value)||1))):undefined;start(x.begin,{goal});return}
 if(x.equip){if(equip(s,x.equip,d))toast('Đã trang bị. Chỉ số đã cập nhật.');else toast('Chưa đủ điều kiện trang bị.');save();render();if($('#modal').open)itemDetails(x.equip);return}
 if(x.claim!==undefined){if(claim(s,+x.claim))toast('Đã nhận thưởng nhiệm vụ');save();render();return}
 if(x.skill){const id=x.skill;if(!d.arts.arts.some(a=>a.id===id&&d.cultivation.realms.findIndex(r=>r.id===a.cultivation_id)<=s.realm))return;const cost=100*((s.skills[id]||0)+1);if(s.stones<cost){toast('Không đủ linh thạch');return}s.stones-=cost;s.skills[id]=(s.skills[id]||0)+1;if(s.skills[id]===1&&s.equippedSkills.length<5&&!s.equippedSkills.includes(id))s.equippedSkills.push(id);save();render();toast('Lĩnh ngộ thành công · +8 công kích');return}
 switch(x.action){case 'bag-filters':bagFilters();break;
 case 'apply-bag-filters':if(bagTab==='equipment'){ownedTier=$('#bag-filter-tier').value;ownedQuality=$('#bag-filter-quality').value;ownedSlot=$('#bag-filter-slot').value}else{bagItemTier=$('#bag-filter-tier').value;bagItemQuality=$('#bag-filter-quality').value;bagItemCategory=$('#bag-filter-category').value;bagItemSearch=$('#bag-filter-search').value.trim()}$('#modal').close();render();break;
 case 'clear-bag-filters':if(bagTab==='equipment'){ownedTier='';ownedQuality='';ownedSlot=''}else{bagItemTier='';bagItemQuality='';bagItemCategory='';bagItemSearch=''}$('#modal').close();render();break;
 case 'quick-sale':quickSale();break;
 case 'battle-details':battleDetails=!battleDetails;render();break;
 case 'bulk-sale':{const selected=Object.keys(qualities).filter(q=>$('#sell-quality-'+q)?.checked);if(!selected.length){toast('Hãy tích chọn ít nhất một phẩm chất.');break}const entries=selected.flatMap(q=>saleSelection(q));if(!entries.length){toast('Không có đồ có thể bán phù hợp bộ lọc và phẩm này.');break}pendingSale={kind:bagTab,entries:entries.map(([id,n])=>({id,n}))};const price=entries.reduce((n,[id,count])=>n+count*(bagTab==='equipment'?equipmentSellPrice(s,id,d):itemSellPrice(id,d)),0),count=entries.reduce((n,e)=>n+e[1],0);modal('Xác nhận bán theo phẩm',`<p>Bán ${count} món ${selected.map(q=>qualities[q].name).join(', ')}, nhận ${format(price)} linh thạch?</p><div class="row">${btn('Hủy','cancel-sale','outline')}${btn('Xác nhận bán','confirm-bulk-sale','primary')}</div>`);break}
 case 'cancel-sale':pendingSale=null;$('#modal').close();break;
 case 'confirm-bulk-sale':{const result=pendingSale?.kind==='equipment'?sellEquipmentBatch(s,pendingSale.entries.map(e=>e.id),d):sellItemBatch(s,pendingSale?.entries,d);pendingSale=null;if(!result){toast('Danh sách đồ đã thay đổi; hãy chọn lại.');break}save();$('#modal').close();render();toast('Đã bán '+result.count+' món · +'+format(result.price)+' linh thạch');break}
 case 'confirm-auto':{const duration=Number($('#auto-duration').value),potionThreshold=Number($('#auto-threshold').value),potionLimit=Number($('#auto-stock').value),retreatHP=Number($('#auto-retreat').value);if(![3600,7200,14400].includes(duration)||![.3,.5,.7].includes(potionThreshold)||![0,.15,.3].includes(retreatHP)||!Number.isInteger(potionLimit)||potionLimit<0||potionLimit>Math.min(9999,s.bag.potion||0)){toast('Kiểm tra lại số lượng đan.');break}const battleConfig={duration,potionThreshold,potionLimit,retreatHP,autoPotion:!!$('#auto-potion').checked,useSkills:!!$('#auto-skills').checked,stopNoPotion:!!$('#auto-empty').checked};start('fight',{duration,battleConfig});break}
 case 'alchemy-clear':alchemyIngredient='';alchemySearch='';alchemyPageIndex=0;render();break;
 case 'confirm-change':{const next=pendingAction;pendingAction=null;if($('#modal').open)$('#modal').close();next?.();break}
 case 'cancel-change':pendingAction=null;$('#modal').close();break;
 case 'stop':stopActivity();break;
 case 'breakthrough':if(breakthrough(s,d)){save();render();modal('Đột phá thành công',`<div class="profession-hero">${icon('star')}<h3>${cultivationLabel(s,d)}</h3></div><p class="muted">Sinh lực đã hồi đầy. Có thể tiếp tục tu hành.</p>${btn('Tiếp tục','close','primary full')}`)}break;
 case 'auto-potion':s.battleSettings.autoPotion=!s.battleSettings.autoPotion;save();render();break;
 case 'item-heal':case 'heal':if(!usePotion(s,d)){toast('Hết đan, HP đã đầy hoặc đan đang hồi chiêu.');break}save();render();if(x.action==='item-heal')itemDetails('potion');break;
 case 'settings':settings();break;case 'close':$('#modal').close();maybeReport();break;case 'all-reports':$('#modal').close();go('reports');save();break;
 case 'rename':s.name=$('#rename').value.trim().slice(0,24)||'Vô Danh Đạo Hữu';save();$('#modal').close();render();toast('Đã lưu tên đạo hữu');break;
 case 'go-herbs':selectedMap=0;go('location');break;
 case 'buy-potion':case 'buy-herb':{const price=x.action==='buy-potion'?50:30;if(s.stones<price){toast('Không đủ linh thạch');break}s.stones-=price;const id=x.action==='buy-potion'?'potion':'herb_001';s.bag[id]=(s.bag[id]||0)+(id==='potion'?1:5);save();render();toast('Đã mua vật phẩm');break}
 case 'sell-herb':if((s.bag.herb_001||0)<5){toast('Cần ít nhất 5 Hoàng Tinh Thảo');break}s.bag.herb_001-=5;s.stones+=15;save();render();toast('Đã bán · +15 linh thạch');break;
 case 'pet-adopt':if(s.pet)break;if(s.stones<300){toast('Cần 300 linh thạch');break}s.stones-=300;s.pet={name:'Linh Hồ',level:1,exp:0,active:true};preparePet(s);save();render();modal('Kết duyên thành công','<p>Linh Hồ đã trở thành bạn đồng hành của đạo hữu. Linh thú cộng chỉ số cho nhân vật và nhận EXP riêng khi hạ quái.</p>'+btn('Đóng','close','primary full'));break;
 case 'pet-toggle':if(s.pet){s.pet.active=!s.pet.active;s.hp=Math.min(s.hp,stats(s,d).hp);save();render()}break;
 case 'pet-feed':if(!s.pet)break;if((s.bag.herb_001||0)<5){toast('Cần 5 Hoàng Tinh Thảo');break}s.bag.herb_001-=5;petExp(s,10);const ps=petStats(s.pet);s.pet.hp=Math.min(ps.hp,s.pet.hp+ps.hp*.3);s.pet.mp=Math.min(ps.mp,s.pet.mp+ps.mp*.3);save();render();modal('Cho ăn hoàn tất','<p>Linh Hồ nhận 10 EXP.</p>'+btn('Đóng','close','primary full'));break;
 case 'pet-train':start('pettrain');break;
 case 'export':{save();const u=URL.createObjectURL(new Blob([JSON.stringify(s,null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=u;link.download='van-dao-save.json';link.click();setTimeout(()=>URL.revokeObjectURL(u),1000);break}
 case 'reset-confirm':modal('Tạo lại nhân vật?',`<p>Tiến trình trên máy này sẽ bị thay thế. Hãy xuất bản lưu nếu cần giữ lại.</p>${btn('Quay lại','settings','full')}${btn('Xác nhận tạo lại','reset','full','style="margin-top:10px;color:var(--red)"')}`);break;
 case 'reset':s=initial();save();$('#modal').close();go('home');break;
 }
});
document.addEventListener('input',ev=>{if(ev.target.id==='forge-count'){forgeCount=Number(ev.target.value);$('#forge-results').innerHTML=forgingResults();return}if(ev.target.id==='alchemy-search'||ev.target.id==='alchemy-count'){if(ev.target.id==='alchemy-search')alchemySearch=ev.target.value;else alchemyCount=Number(ev.target.value);alchemyPageIndex=0;$('#alchemy-results').innerHTML=alchemyResults();return}if(ev.target.id==='gear-search'){gearSearch=ev.target.value;gearPage=0;$('#gear-catalog-results').innerHTML=gearCatalogResults();return}if(ev.target.id==='catalog-search'){catalogSearch=ev.target.value;catalogPage=0;$('#catalog-results').innerHTML=catalogResults()}});
document.addEventListener('change',async ev=>{if(ev.target.id==='forge-tier'||ev.target.id==='forge-slot'){if(ev.target.id==='forge-tier')forgeTier=ev.target.value;else forgeSlot=ev.target.value;$('#forge-results').innerHTML=forgingResults();return}if(ev.target.id==='alchemy-tier'||ev.target.id==='alchemy-category'){if(ev.target.id==='alchemy-tier')alchemyTier=ev.target.value;else alchemyCategory=ev.target.value;alchemyPageIndex=0;$('#alchemy-results').innerHTML=alchemyResults();return}const equipmentFilters={'gear-tier':v=>gearTier=v,'gear-slot':v=>gearSlot=v,'gear-preview-quality':v=>gearPreviewQuality=v};if(equipmentFilters[ev.target.id]){equipmentFilters[ev.target.id](ev.target.value);gearPage=0;$('#gear-catalog-results').innerHTML=gearCatalogResults();return}if(ev.target.id==='item-tier'||ev.target.id==='item-quality'){if(ev.target.id==='item-tier')itemTier=ev.target.value;else itemQuality=ev.target.value;catalogPage=0;$('#catalog-results').innerHTML=catalogResults();return}if(ev.target.id==='catalog-category'){catalogCategory=ev.target.value;catalogPage=0;$('#catalog-results').innerHTML=catalogResults();return}if(ev.target.id==='save-import'){const file=ev.target.files[0];if(!file)return;if(file.size>2e6){toast('Bản lưu cần nhỏ hơn 2 MB');return}const next=loadSave(await file.text(),d);if(!next){toast('Bản lưu không hợp lệ');return}s=next;s.last=Date.now();save();$('#modal').close();go('home');maybeReport()}});
let mapFrame=null;
function mapViewKey(){return world}
function mapView(){const key=mapViewKey();if(!mapViews.has(key)){const viewport=$('.map-viewport');mapViews.set(key,worldLocations(d,world).some(m=>m.i===s.map)?focusedMapPoint(journeyMapPosition(s,d),viewport?.clientWidth||320,viewport?.clientHeight||420):focusedMap(d,world,s.map,null,viewport?.clientWidth||320,viewport?.clientHeight||420));}return mapViews.get(key)}
function fitMapFrame(){const viewport=$('.map-viewport'),nav=$('#bottom-nav');if(!viewport?.style||!viewport.getBoundingClientRect)return;const vv=window.visualViewport,bottom=(vv?.offsetTop||0)+(vv?.height||window.innerHeight||0);if(!bottom)return;const top=viewport.getBoundingClientRect().top,navTop=nav?.getBoundingClientRect?.().top??bottom;viewport.style.height=mapFrameHeight(top,navTop,bottom)+'px'}
function applyMapView(){const scene=$('.map-scene'),viewport=$('.map-viewport');if(!scene?.style||!viewport)return;fitMapFrame();const width=viewport.clientWidth,height=viewport.clientHeight;if(!width||!height)return;const key=mapViewKey(),exists=mapViews.has(key);let view=mapView();if(exists&&mapFrame?.key===key&&(mapFrame.width!==width||mapFrame.height!==height))view=resizeMap(view,mapFrame.width,mapFrame.height,width,height);view=constrainMap(view,width,height);const base=atlasSize(width,height);mapViews.set(key,view);mapFrame={key,width,height};scene.style.width=base.width+'px';scene.style.height=base.height+'px';scene.style.transform=`translate(${view.x}px,${view.y}px) scale(${view.scale})`;scene.style.setProperty?.('--map-inverse',1/view.scale);viewport.classList?.toggle?.('show-locations',mapDetailLevel(view.scale,base.width)==='location');}
function gestureStart(){const points=[...mapGesture.pointers.values()],v=mapGesture.viewport;if(!v||!points.length)return;const rect=v.getBoundingClientRect();mapGesture.origin={...mapView()};mapGesture.center={x:points.reduce((n,p)=>n+p.x,0)/points.length-rect.left,y:points.reduce((n,p)=>n+p.y,0)/points.length-rect.top};mapGesture.distance=points.length>1?Math.hypot(points[0].x-points[1].x,points[0].y-points[1].y):0}
document.addEventListener('pointerdown',ev=>{if(tab!=='world'||(ev.pointerType==='mouse'&&ev.button!==0))return;const viewport=ev.target.closest?.('.map-viewport');if(!viewport)return;if(mapGesture.viewport!==viewport){mapGesture.pointers.clear();mapGesture.viewport=viewport}if(!mapGesture.pointers.size){mapGesture.dragged=false;mapGesture.suppress=false}mapGesture.pointers.set(ev.pointerId,{x:ev.clientX,y:ev.clientY});gestureStart()});
document.addEventListener('pointermove',ev=>{if(!mapGesture.pointers.has(ev.pointerId))return;const viewport=mapGesture.viewport;if(!viewport?.isConnected){mapGesture.pointers.clear();return}mapGesture.pointers.set(ev.pointerId,{x:ev.clientX,y:ev.clientY});const points=[...mapGesture.pointers.values()],rect=viewport.getBoundingClientRect(),center={x:points.reduce((n,p)=>n+p.x,0)/points.length-rect.left,y:points.reduce((n,p)=>n+p.y,0)/points.length-rect.top},origin=mapGesture.origin,base=mapGesture.center,dx=center.x-base.x,dy=center.y-base.y;let scale=origin.scale;if(points.length>1&&mapGesture.distance>0)scale=origin.scale*Math.hypot(points[0].x-points[1].x,points[0].y-points[1].y)/mapGesture.distance;
if(!mapGesture.dragged&&(Math.hypot(dx,dy)>6||Math.abs(scale-origin.scale)>.03)){mapGesture.dragged=true;viewport.setPointerCapture?.(ev.pointerId)}if(!mapGesture.dragged)return;ev.preventDefault();mapGesture.suppress=true;const view=zoomMap(origin,scale,base,viewport.clientWidth,viewport.clientHeight);mapViews.set(mapViewKey(),constrainMap({...view,x:view.x+dx,y:view.y+dy},viewport.clientWidth,viewport.clientHeight));applyMapView()});
function endMapPointer(ev){if(!mapGesture.pointers.has(ev.pointerId))return;mapGesture.pointers.delete(ev.pointerId);if(mapGesture.pointers.size)gestureStart();else if(mapGesture.dragged)mapGesture.suppress=true}
document.addEventListener('pointerup',endMapPointer);document.addEventListener('pointercancel',ev=>{endMapPointer(ev);mapGesture.pointers.clear()});
document.addEventListener('wheel',ev=>{if(tab!=='world')return;const viewport=ev.target.closest?.('.map-viewport');if(!viewport)return;ev.preventDefault();const rect=viewport.getBoundingClientRect();mapViews.set(mapViewKey(),zoomMap(mapView(),mapView().scale*Math.exp(-ev.deltaY*.002),{x:ev.clientX-rect.left,y:ev.clientY-rect.top},viewport.clientWidth,viewport.clientHeight));applyMapView()},{passive:false});
document.addEventListener('dblclick',ev=>{if(tab!=='world'||ev.target.closest?.('button'))return;const viewport=ev.target.closest?.('.map-viewport');if(!viewport)return;ev.preventDefault();const rect=viewport.getBoundingClientRect(),view=mapView();mapViews.set(mapViewKey(),zoomMap(view,view.scale>=3.5?1.6:view.scale*1.4,{x:ev.clientX-rect.left,y:ev.clientY-rect.top},viewport.clientWidth,viewport.clientHeight));applyMapView()});
window.addEventListener('resize',()=>{if(tab==='world')applyMapView()});window.visualViewport?.addEventListener('resize',()=>{if(tab==='world')applyMapView()});

function arrivalNavigation(){if(s.battleDestination!==undefined&&s.activity!=='travel'){if(s.battleDestination===s.map)tab='battle';delete s.battleDestination}}
let lastTick=Date.now();function advance(){const now=Date.now(),seconds=Math.min(28800,Math.floor((now-lastTick)/1000));if(seconds<1)return;lastTick=seconds===28800?now:lastTick+seconds*1000;const completed=tick(s,d,seconds);if(tab!=='battle'||$('#modal').open){lastFxId=s.combatEventSerial||0;fxItems=[];}arrivalNavigation();save();info();updateAtlasJourney();if(!$('#modal').open){if(tab==='profession'&&!completed.length){const panel=$('.activity-panel');if(panel)panel.outerHTML=activity();if(profession==='alchemy'&&s.session?.type==='recipe'&&s.session.seconds%5===0)$('#alchemy-results').innerHTML=alchemyResults()}else if(['home','cultivation','combatStats','battle','pets'].includes(tab)||completed.length){const scroll=window.scrollY;render();window.scrollTo(0,scroll)}maybeReport()}}
async function boot(){try{const keys={world:'world',cultivation:'cultivation',combat:'combat_entities',equipment:'equipment',arts:'arts_and_relics',items:'items_and_recipes',visuals:'world_visuals',appendix:'appendix_a',art:'entity_art',nodes:'map_nodes',itemArt:'item_art',locationVisuals:'location_visuals',skins:'skins'};d=Object.fromEntries(await Promise.all(Object.entries(keys).map(async([k,f])=>{const r=await fetch('data/'+f+'.json');if(!r.ok)throw Error(f);return [k,await r.json()]})));let raw;try{raw=localStorage.getItem(key)}catch{storageOK=false}s=loadSave(raw,d)||initial();const elapsed=Math.min(28800,Math.max(0,Math.floor((Date.now()-s.last)/1000)));if(elapsed>0)tick(s,d,elapsed);selectedMap=s.map;world=mapWorld(current());arrivalNavigation();save();render();maybeReport();lastTick=Date.now();setInterval(advance,1000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)advance();else save()});window.addEventListener('pagehide',save)}catch(e){$('#main').innerHTML='<div class="card"><h3>Chưa nạp được dữ liệu</h3><p>Hãy tải lại trang hoặc kiểm tra kết nối.</p><button onclick="location.reload()">Thử lại</button></div>';console.error(e)}}boot();
